'use strict';
(function(root){
 const edition={"schema":"qp-story-edition-v1","edition":"2026-11-14","boundary":"Dated source-attributed educational story; independent review and publication pending. Not a full 40-point paper.","stories":[{"id":"infr-005","title":"The gap in 24th Street: why Pueblo is studying a railroad bridge","questions":["24th Street bridge planning","24th Street bridge","What is happening with the 24th Street bridge?","Why is Pueblo planning a 24th Street bridge?","Is the 24th Street bridge funded for construction?"],"checked":"2026-11-14","reviewBy":"2026-12-01","summary":"Pueblo is studying a new crossing over the BNSF tracks at 24th Street. Its intended purpose is to connect the West Side more directly to downtown. The City reports that design work has funding; the bridge's construction remains unfunded in the July 16 project update. [S1]","chapters":[{"kind":"context","heading":"Why a street can stop at the tracks","text":"The railroad separates street segments between Atlanta and Adrian avenues. A bridge could connect those segments without relying on a crossing at track level. The proposal also examines travel along the corridor, not just the bridge itself. [S1,S3]"},{"kind":"chronology","heading":"From an idea to design","text":"The City reports a $3.3 million design and preliminary-engineering agreement approved in December 2025. On June 25, 2026, the City held an open house at Centennial High School. The associated comment period ran through July 31. The published study window spans 2026–2027; construction timing is undetermined. [S1,S2]"},{"kind":"people","heading":"Who is doing what?","text":"The City is leading the study; Council approved the design agreement according to its project page. Public Works director Andrew Hayes described the design phase in July reporting. BNSF is the railroad crossed; the specific railroad agreement, design contractor and approval chain are not established by the sources reviewed here. [S1,S3]"},{"kind":"money","heading":"What the $3.3 million actually buys","text":"The City says the agreement advances design and preliminary engineering, supported by federal RAISE funding. It is not a construction award or an amount already paid. The $16.8 million grant cited in the August 2025 announcement concerns the separately described Sun Mountain roadway and bus-stop projects; do not assign that entire amount to the bridge or add it to the design agreement. [S1,S4]"},{"kind":"meaning","heading":"Why this matters for daily life","text":"For someone who lives on one side and needs to reach the other, the issue is access. A more direct route may help drivers, transit riders, people walking or cycling, and emergency responders. These are intended improvements, not measured travel-time or safety gains. [S1]"},{"kind":"options","heading":"What choices remain?","text":"Q assessment: compare the proposed crossing and corridor layouts with existing-route improvements and a no-build baseline. Examine accessibility, rail clearances, drainage, property impacts, maintenance, emergency access and lifecycle costs. These are evaluation options, not a statement of the City's chosen design."},{"kind":"future","heading":"What to watch through 2027","text":"Look for the selected design, environmental review, project-specific cost estimate, grant awards, construction authorization and actual payments. Check whether alternative routes remain usable during construction or funding delays. Q assessment: the bridge and nearby projects should be coordinated but tracked in separate ledgers."}],"unknowns":["No final design, construction award or completion date established.","No current project-specific construction estimate, payment ledger or railroad agreement verified.","This review does not establish quantified benefits, environmental effects or neighborhood preferences."],"sources":[{"id":"S1","title":"City of Pueblo — dedicated 24th Street Bridge project page (updated July 16, 2026)","url":"https://www.pueblo.us/3108/24th-Street-Bridge-over-BNSF-Railroad-an"},{"id":"S2","title":"City — West Side Improvements Project","url":"https://www.pueblo.us/3056/West-Side-Improvements-Project"},{"id":"S3","title":"KRDO — July 29, 2026 project reporting","url":"https://krdo.com/news/top-stories/2026/07/29/pueblo-starts-initial-steps-toward-bridge-project-to-connect-two-closed-ends-of-24th-street-on-west-side/"},{"id":"S4","title":"City — August 27, 2025 West Side announcement (separate projects)","url":"https://www.pueblo.us/m/newsflash/Home/Detail/4866"}],"route":"connections.html?issue=infr-005","keywords":["24th street bridge","24th street railroad bridge"]},{"id":"reg-023","title":"Can a data center create lasting public value in Pueblo?","questions":["Data center considerations","What should Pueblo consider before approving a data center?","What happened to Colorado's 2026 data center bills?"],"summary":"Colorado considered competing approaches to large data centers in 2026, but both bills were postponed indefinitely. Pueblo's local project status, resource commitments and net public benefit need separate verification. [S1,S2]","checked":"2026-11-14","reviewBy":"2026-12-01","chapters":[{"heading":"Where the issue begins","text":"Computing facilities need reliable electricity, networking, cooling and land. A region considering a large facility should examine the incremental resources required and not assume the investment automatically benefits existing residents."},{"heading":"The 2026 policy debate","text":"HB26-1030 proposed development incentives and utility modernization. The House committee postponed it indefinitely May 7. SB26-102 proposed additional resource and accountability requirements; the Senate committee postponed it indefinitely May 11. Neither proposal became law. [S1,S2]"},{"heading":"Who would be involved","text":"A specific project may involve a developer, utilities, local permitting authorities and state regulators. Those are potentially responsible roles, not identified participants in a confirmed Pueblo proposal."},{"heading":"Follow the costs","text":"Q assessment: identify power and cooling requirements, construction and permanent jobs, tax concessions, infrastructure financing and shutdown liabilities. Compare a no-project baseline and alternative industrial uses. Do not report modeled benefits as achieved outcomes."},{"heading":"What comes next","text":"Seek an actual application and site, utility capacity and water plan, enforceable public obligations, evidence of public notice and a lifecycle cost model. Track future legislative proposals separately."}],"unknowns":["No specific approved Pueblo data center, site, developer, power load or water demand verified here.","No regional net public benefit or project-specific cost estimate established."],"sources":[{"id":"S1","title":"Colorado General Assembly — HB26-1030","url":"https://leg.colorado.gov/bills/HB26-1030"},{"id":"S2","title":"Colorado General Assembly — SB26-102","url":"https://leg.colorado.gov/bills/SB26-102"}],"keywords":["data center","data centers","large-load data"],"route":"issues.html#REG-023"},{"id":"reg-047","title":"License-plate readers: public safety, privacy and oversight","questions":["Flock cameras","Pueblo ALPR policy","What does Pueblo's August 2026 license plate reader directive say?"],"summary":"On August 20, 2026 Pueblo Police Chief Chris Noeller issued interim Directive 26-2 for department-controlled automated license-plate readers (ALPR). The directive superseded Policy 429 pending a permanent revision. Its existence does not establish compliance, vendor coverage or effectiveness. [S1]","checked":"2026-11-14","reviewBy":"2026-12-01","chapters":[{"heading":"How the system works","text":"Automated readers can record a vehicle plate together with time, location and other vehicle information. An automated match is a lead rather than confirmation of identity or legal status. [S1]"},{"heading":"The documented change","text":"Directive 26-2 sets interim operating requirements across department-controlled platforms. It distinguishes authorized official uses from personal or unauthorized searches and limits how broadly searches should be conducted. [S1]"},{"heading":"People and authority","text":"The Police Department issued the directive. Governing law, policy, court orders and contracts remain relevant. No claim about a person's behavior follows from the policy alone."},{"heading":"What the public should be able to examine","text":"Q assessment: request vendor-specific contracts, lawful access controls, retention, sharing rules, audit results, complaints, false matches and measured case outcomes. Balance effectiveness against privacy and lifecycle cost, without publishing individual vehicle records or device locations."},{"heading":"What comes next","text":"Verify the permanent policy and actual implementation; compare privacy-preserving alternatives, oversight and correction mechanisms."}],"unknowns":["Current permanent policy status, vendor-specific inventory, total cost and measured effectiveness not verified.","No finding of unlawful conduct or compliance certification."],"sources":[{"id":"S1","title":"Pueblo Police Department — Directive 26-2, August 20, 2026","url":"https://www.pueblo.us/DocumentCenter/View/46656/26-02-ALPR-Directive"}],"keywords":["flock camera","flock cameras","alpr","license plate reader","license plate readers"],"route":"issues.html#REG-047"},{"id":"reg-009","title":"The museum funding debate: an educational opportunity and a public investment decision","questions":["Da Vinci Museum funding","Why was the Leonardo da Vinci Museum funding request denied?","What happened to the Pueblo museum funding request?"],"summary":"On September 14, 2026, Pueblo Council reportedly rejected an $885,000 museum funding request by two votes in favor and five against. This is the reported result of that request, not evidence that the museum closed or that no future financing is possible. [S1,S2]","checked":"2026-11-14","reviewBy":"2026-12-01","chapters":[{"heading":"Where the question began","text":"The Leonardo da Vinci Museum sought economic-development funding. Local reporting describes an earlier request of roughly $1.8 million, later reduced to $885,000. [S1]"},{"heading":"The decision","text":"A delayed vote returned to Council in September following questions about eligibility and proposed uses. The Sept 8 work session was reported to include the mayor and museum representatives. Council then rejected the request Sept 14. [S1,S2]"},{"heading":"Follow the money","text":"The requested sum was not an award or disbursement. Reporting describes proposed educational programming, signage and a cafe. The controlling agreement, enacted criteria and primary vote records remain needed for a full finance investigation. [S1]"},{"heading":"Why residents care","text":"Q assessment: cultural and educational benefits, visitor spending, jobs and operating sustainability deserve separate measures. Compare alternative financing, support with enforceable milestones and no public grant. No misconduct conclusion is supported by a contested funding vote."},{"heading":"The next chapter","text":"Track actual attendance, operating costs, independently verified outcomes and any subsequent financing decision."}],"unknowns":["Final primary ordinance and official minutes not independently reconciled in this edition.","Current financial condition and subsequent funding unverified."],"sources":[{"id":"S1","title":"KKTV — September 14–15, 2026 funding decision","url":"https://www.kktv.com/2026/09/15/leonardo-da-vinci-museum-funding-fails-during-city-council-vote-monday/"},{"id":"S2","title":"Pueblo Chieftain — September 10 preview, via AOL","url":"https://www.aol.com/articles/pueblo-council-revisit-ordinances-da-100458000.html"}],"keywords":["da vinci museum","museum funding","leonardo museum"],"route":"issues.html#REG-009"},{"id":"reg-028","title":"Pueblo Zoo: conservation, learning and the funding vote","questions":["Pueblo Zoo","Pueblo Zoo sales tax","What happened to the zoo tax measure in November 2026?"],"summary":"The Colorado Municipal League's preliminary results report passage of a 0.167% City sales-tax increase through 2031 for a dedicated zoo fund. Pueblo County's November 13 results remain labeled unofficial. Certification and implementation must be checked before treating the measure as final. [S1,S2]","checked":"2026-11-14","reviewBy":"2026-12-01","chapters":[{"heading":"Beyond an attraction","text":"The zoo publishes conservation and local ecology resources about prairie biodiversity and pollinators. These are educational programs, separate from any claim about the financial performance of the institution. [S3]"},{"heading":"A decision in November","text":"The November 2026 local vote considered dedicated tax funding. CML reports the measure passed provisionally; the County election page provides the official results-update route. [S1,S2]"},{"heading":"Follow the money","text":"Q assessment: distinguish the tax rate, projected revenue, actual collections, fund balances, operating and capital spending and outcomes. No collections from the proposed future period are presented as already received."},{"heading":"Learning and conservation","text":"Link the zoo's educational material to Pueblo's prairie, habitats and pollination resources. An educational program's existence is not proof of specific gains in biodiversity."},{"heading":"What to watch","text":"Check certified results, implementation terms, budgets, expenditures and independently reported conservation and learning outcomes."}],"unknowns":["Final certification and tax collections not established here.","No independent financial, conservation or education outcome audit."],"sources":[{"id":"S1","title":"Colorado Municipal League — fall 2026 unofficial results","url":"https://www.cml.org/home/publications-news/article-detail/fall-2026-municipal-election-results"},{"id":"S2","title":"Pueblo County — November 2026 election results","url":"https://pueblocounty.gov/clerk-and-recorder-department/election-results-november-2026"},{"id":"S3","title":"Pueblo Zoo — conservation","url":"https://www.pueblozoo.org/conservation"}],"keywords":["pueblo zoo","zoo tax","zoo funding"],"route":"issues.html#REG-028"},{"id":"heritage-borderlands","collection":"history","title":"Before the trading post: the Arkansas River borderlands","questions":["Before the trading post","What was Pueblo like before El Pueblo?"],"summary":"Pueblo's history predates the 1842 trading post. The Arkansas River region was home to Indigenous peoples and became a place of migration, commerce and changing political boundaries. [S1,S2]","checked":"2026-11-14","reviewBy":"2027-11-14","chapters":[{"heading":"The place before the city","text":"Southern Colorado's borderlands connected communities long before modern municipal boundaries. Indigenous nations have distinct histories and present-day sovereignty; a single settler account cannot represent them all."},{"heading":"A crossroads of cultures","text":"History Colorado's borderlands exhibition traces the interactions of Indigenous, Mexican and territorial communities. The later El Pueblo settlement belongs within this larger history, not at its beginning. [S1,S2]"},{"heading":"Read the evidence","text":"Compare tribal accounts, archaeology, treaties and historical records. Examine whose voices survive in the archive and whose are missing."}],"unknowns":["A complete nation-specific local chronology requires further research with tribal sources."],"sources":[{"id":"S1","title":"History Colorado — Southern Colorado borderlands","url":"https://www.historycolorado.org/exhibit/borderlands-southern-colorado-santa-fe-trail"},{"id":"S2","title":"Advisory Council on Historic Preservation — Pueblo","url":"https://www.achp.gov/preserve-america/community/pueblo-colorado"}],"keywords":["before the trading post","indigenous pueblo history"],"route":"learn-pueblo.html#story=heritage-borderlands"},{"id":"heritage-el-pueblo","collection":"history","title":"El Pueblo: a trading post at a changing frontier","questions":["1842–1854 • El Pueblo","What was the El Pueblo trading post?","History of El Pueblo"],"summary":"The original El Pueblo trading post operated from 1842 until 1854 at a cultural and commercial crossroads on the Arkansas River. [S1,S2]","checked":"2026-11-14","reviewBy":"2027-11-14","chapters":[{"heading":"1842 — a place to trade","text":"The river marked an international boundary at the time. Traders, settlers and Indigenous people exchanged goods and participated in a wider regional economy. [S2]"},{"heading":"1854 — the post's end","text":"Tensions and violence culminated in the attack at Christmas 1854. The post was abandoned. A full account requires examining Indigenous perspectives and the preceding political and territorial changes, not attributing a single motive. [S2]"},{"heading":"How we learn about it today","text":"History Colorado's reconstruction illustrates aspects of mid-nineteenth-century daily life; it is not the entire original building. Archaeological evidence and historical documents help establish the site's story. [S1]"}],"unknowns":["A full account of individuals, preceding conflicts and Indigenous perspectives is not established here."],"sources":[{"id":"S1","title":"History Colorado — El Pueblo trading post","url":"https://www.historycolorado.org/media/8439"},{"id":"S2","title":"Advisory Council on Historic Preservation — Pueblo, Colorado","url":"https://www.achp.gov/preserve-america/community/pueblo-colorado"}],"keywords":["el pueblo trading post","fort pueblo"],"route":"learn-pueblo.html#story=heritage-el-pueblo"},{"id":"heritage-four-towns","collection":"history","title":"Four communities, one city: how Pueblo took shape","questions":["Four towns become Pueblo","How did Pueblo become one city?","History of Bessemer annexation"],"summary":"Modern Pueblo emerged through a sequence of municipal changes: three communities consolidated in April 1886, followed by Bessemer's annexation in March 1894. [S1]","checked":"2026-11-14","reviewBy":"2027-11-14","chapters":[{"heading":"Before consolidation","text":"Pueblo incorporated in 1870, South Pueblo in 1873 and Central Pueblo in 1882. Each was a separate municipality. [S1]"},{"heading":"March and April 1886 — joining together","text":"After a special election on March 9, the three communities consolidated under state legislation. [S1]"},{"heading":"1894 — Bessemer joins","text":"Bessemer had incorporated in July 1886. On March 21, 1894 it was annexed under legislation approved the preceding year. [S1]"},{"heading":"The legacy","text":"The City records these changes in its 2014 historical brief, citing explanatory notes to the 1908 ordinances. Neighborhood identities and the history of municipal boundaries can help residents make sense of historic maps today."}],"unknowns":["The individual negotiations, contemporary public debate and detailed boundary maps require original records."],"sources":[{"id":"S1","title":"City of Pueblo — 2014 State of the City Brief, page 7, Forging of the Community","url":"https://www.pueblo.us/ArchiveCenter/ViewFile/Item/1102"}],"keywords":["four towns","bessemer annexation","pueblo consolidation"],"route":"learn-pueblo.html#story=heritage-four-towns"},{"id":"heritage-rail-fair","collection":"history","title":"1872: railroads, agriculture and Pueblo's State Fair","questions":["1872 • Railroads and the State Fair","How did railroads and the State Fair shape Pueblo?"],"summary":"In 1872 Pueblo gained a rail connection and hosted an agricultural and industrial fair. Both linked the region to larger markets, although they were separate developments. [S1,S2]","checked":"2026-11-14","reviewBy":"2027-11-14","chapters":[{"heading":"The rail connection","text":"The Denver & Rio Grande arrived in 1872, connecting Pueblo to other Front Range communities. Rail access supported industrial and agricultural commerce. [S1]"},{"heading":"The fair begins","text":"The Southern Colorado Agricultural and Industrial Association held its fair on October 9, 1872. The fair incorporated in 1886 and changed locations as it developed. [S2]"},{"heading":"Why this matters","text":"Rail transport moved goods and people; agricultural exhibitions promoted producers and skills. To evaluate later economic effects, compare dated freight, attendance, employment and financial records rather than assuming these two events explain all growth."}],"unknowns":["The exact economic contribution of either development and a complete fair-site timeline are not established in this edition."],"sources":[{"id":"S1","title":"Visit Pueblo — History and Heritage","url":"https://visitpueblo.org/listing/history/"},{"id":"S2","title":"Colorado State Fair — History","url":"https://coloradostatefair.com/about/history/"}],"keywords":["state fair history","railroad history"],"route":"learn-pueblo.html#story=heritage-rail-fair"},{"id":"heritage-steel","collection":"history","title":"From railroads to steel: the people who built an industrial city","questions":["Industry, migration and workers","Why is Pueblo called the Steel City?","History of Pueblo steel"],"summary":"Pueblo's steel industry grew with rail transport, nearby fuel resources and a diverse workforce. Colorado Fuel & Iron was formed by a merger in 1892, after earlier steel operations had already begun. [S1,S2]","checked":"2026-11-14","reviewBy":"2027-11-14","chapters":[{"heading":"The industrial origins","text":"Steelworks Center of the West connects early steel production to the railroad development that began in 1872. The archive describes initial production in 1880; company formation and plant milestones must be kept distinct. [S1]"},{"heading":"1892 — consolidation of industry","text":"History Colorado describes the merger that formed CF&I, integrating coal production and steelmaking. [S2]"},{"heading":"The human story","text":"Expansion drew workers from Mexico, Europe, Japan and elsewhere. Families and neighborhoods became part of a wider industrial network of mills, mines and camps. [S2]"},{"heading":"What to examine next","text":"Explore the CF&I archives for actual employment records, working conditions, labor organizing, photographs and community accounts. Compare historical operations with today's industry without assuming continuity of ownership or technology."}],"unknowns":["This is not a complete labor history or an assessment of current industrial employment."],"sources":[{"id":"S1","title":"Steelworks Center of the West — History and archives","url":"https://www.steelworks.us/education/history/"},{"id":"S2","title":"History Colorado — Making Americans, November 29, 2024","url":"https://www.historycolorado.org/story/2024/11/29/making-americans"}],"keywords":["pueblo steel","steel city","steelworks history","cf&i history"],"route":"learn-pueblo.html#story=heritage-steel"},{"id":"heritage-flood","collection":"history","title":"June 1921: when the rivers overtook Pueblo","questions":["1921 • The flood","What happened in the 1921 Pueblo flood?","1921 Pueblo flood history"],"summary":"Heavy rains in early June 1921 caused the Arkansas River and Fountain Creek to overflow, devastating downtown Pueblo. The disaster led to major flood-protection changes; the exact death toll remains uncertain. [S1,S2]","checked":"2026-11-14","reviewBy":"2027-11-14","chapters":[{"heading":"The rain arrives","text":"Rainfall began west of Pueblo on June 2, with intense storms affecting the city and Fountain Creek on June 3. The rivers rose rapidly. [S1,S2]"},{"heading":"The consequences","text":"The National Weather Service describes extensive inundation in the commercial district and damage across the valley. The Conservancy District records further flooding on June 4 and notes that the full number of deaths is not known. [S1,S2]"},{"heading":"Rebuilding and prevention","text":"The historic river channel through downtown was subsequently changed. Flood protection and emergency preparedness became enduring regional concerns. [S1]"},{"heading":"Learn from the event","text":"Compare original photographs, newspapers and engineering records with modern hazard maps. Historical disaster impacts do not establish the risk to any particular property today."}],"unknowns":["Exact fatalities, individual stories, full recovery expenditures and the detailed engineering chronology need further archival reconciliation."],"sources":[{"id":"S1","title":"Pueblo Conservancy District — History","url":"https://pueblolevee.org/history/"},{"id":"S2","title":"National Weather Service — Colorado historical floods","url":"https://www.weather.gov/safety/flood-states-co"}],"keywords":["1921 pueblo flood","1921 flood"],"route":"learn-pueblo.html#story=heritage-flood"},{"id":"heritage-riverwalk","collection":"history","title":"How Pueblo brought the river back downtown","questions":["1999 • Riverwalk revival","How did the Pueblo Riverwalk begin?"],"summary":"The Riverwalk developed from a 1991 community initiative, a City commission established in 1993, and a project opening in 1999, according to the Riverwalk's official history. [S1]","checked":"2026-11-14","reviewBy":"2027-11-14","chapters":[{"heading":"Why the river had moved","text":"After the devastating 1921 flood, the river was diverted from its historic downtown course. [S1]"},{"heading":"A community vision","text":"In 1991 residents proposed a downtown riverwalk. The City established the HARP Commission in 1993 to oversee development and citizen fundraising. [S1]"},{"heading":"1999 — opening","text":"The official Riverwalk history dates the opening to 1999. The project created a downtown gathering place connected to the city's river heritage. [S1]"},{"heading":"The continuing story","text":"The Riverwalk reports completion of a boathouse and approximately 500-foot channel extension in 2026. This is its reported development milestone, not an independent cost or tourism-outcome audit. [S1]"}],"unknowns":["Original financing, construction cost, grand-opening date distinctions and measured economic outcomes need further reconciliation."],"sources":[{"id":"S1","title":"Historic Arkansas Riverwalk — Our History","url":"https://www.puebloriverwalk.org/173/About"}],"keywords":["riverwalk history","riverwalk revival","pueblo riverwalk begin"],"route":"learn-pueblo.html#story=heritage-riverwalk"},{"id":"edu-014","title":"District 70, Riverstone Academy and the fight over public decision-making","questions":["District 70 Riverstone controversy","What happened with Riverstone Academy and the District 70 school board?","Pueblo District 70 board drama","Forging Pueblo and Riverstone Academy"],"summary":"A school authorization in June 2025 led to disputes over religious public education, a board resignation, litigation and changes to public school authorization law. A reported August 2026 ruling invalidated the agreement and a later board appointment. The district's current members page lists Jonathan Lewis in District II. [S1,S2,S3,S4,S5,S6]","checked":"2026-11-14","reviewBy":"2026-12-01","chapters":[{"heading":"Where it began","text":"In June 2025 D70 considered an agreement allowing ERBOCES-authorized Riverstone to operate within district boundaries. Local education reporting subsequently examined the proposal as part of a debate over religious public schools. [S1]"},{"heading":"Opening and public debate","text":"The school opened in August 2025. Its authorizer publicly described it as a Christian public school in October. The reporting traced the roles of the authorizer, local district and education advocates, including Forging Pueblo. Documented affiliation or shared views alone do not establish coordinated control, unlawful conduct or disqualification. [S1]"},{"heading":"Board changes and court action","text":"Anne Ochs resigned in December 2025. Three unsuccessful candidates later challenged the board's selection process and prior meeting notice. Reporting on the August 11, 2026 district court ruling describes two open-meetings violations and invalidated decisions. The primary judgment must be obtained before legal conclusions beyond the reported ruling. [S1,S2]"},{"heading":"Closure and statewide changes","text":"Riverstone closed in May 2026. The enacted SB26-023 restricts statewide BOCES authorization and certain contract schools and requires independence and oversight of education management providers. This is not a general prohibition on private religious schools. [S1,S3]"},{"heading":"The most recent chapter","text":"October reporting says the board voted 3–1 to discontinue its appeal on October 6. The district announced public interviews and a vote for October 20. Its current roster lists Jonathan Lewis as District II director; the original vote minutes and effective date remain to be reconciled. [S4,S5,S6]"},{"heading":"Follow the money and protect students","text":"October reporting describes potential fees and costs above $78,000. This is not a verified final award or payment. Q assessment: reconcile legal invoices, the fee order, payment records, authorization dates and effects on educational services before estimating costs. Avoid exposing student records. [S7]"},{"heading":"Next decisions","text":"Track the closing financial ledger, legal disposition and public notice reforms; compare transparent, legally reviewed authorizer and contractor models. For families, use the district and CDE guidance, not an inference from a political controversy."}],"unknowns":["Original court orders, October meeting minutes and final fee award or payments have not been directly reconciled.","No finding of coordinated control, criminal misconduct or individual motive is made.","Current program-level authorization and student outcomes require direct evidence."],"sources":[{"id":"S1","title":"CPR / Chalkbeat — November 2 retrospective","url":"https://www.cpr.org/2026/11/02/riverstone-academy-closure-impact-public-christian-school/"},{"id":"S2","title":"Chalkbeat — August 12 court ruling","url":"https://www.chalkbeat.org/colorado/2026/08/12/pueblo-district-70-school-board-violated-state-law-judge-rules/"},{"id":"S3","title":"Colorado General Assembly — enacted SB26-023","url":"https://leg.colorado.gov/bills/sb26-023"},{"id":"S4","title":"Pueblo Chieftain — October 9 appeal report","url":"https://www.aol.com/articles/pueblo-d70-board-drops-lawsuit-100546000.html"},{"id":"S5","title":"District 70 — October 20 candidate interviews","url":"https://www.district70.org/district-information/directory-of-staff/applicants-for-board-appointment"},{"id":"S6","title":"District 70 — current members","url":"https://www.district70.org/district-information/directory-of-staff/members"},{"id":"S7","title":"Pueblo Chieftain — October 16 potential fees","url":"https://www.aol.com/articles/pueblo-d70-could-owe-more-100210000.html"}],"keywords":["riverstone academy","district 70","d70 board","forging pueblo"],"route":"connections.html?issue=edu-014"},{"id":"case-school-governance","title":"What happens to students when a school authorizer dissolves?","questions":["ERBOCES dissolution","What happened to ERBOCES schools and students?","Pueblo school authorizer transition","What happened to Pueblo School for the Arts and Sciences charter application?"],"summary":"CDE documents a temporary transfer of ERBOCES online schools to District 49 for 2026–27 and a separate application process for affected homeschool programs. In October the State Board sent PSAS's charter application back to District 60 for reconsideration. Long-term authorizations and school-specific arrangements remain important. [S1,S2,S3,S4]","checked":"2026-11-14","reviewBy":"2026-12-01","chapters":[{"heading":"How an authorizer works","text":"A BOCES is a public education cooperative. Authorizing or administering an education program is different from operating it; contractors can provide services under agreements. Authority, oversight, funding and student service continuity must be tracked separately. [S1,S2]"},{"heading":"August 2026 — dissolution","text":"CDE reports that District 49 voted to dissolve ERBOCES on August 17 and the state board approved an emergency transfer on August 19. The transfer covers 2026–27; permanent authorization must use the regular process for 2027–28. [S1,S2]"},{"heading":"Who is affected","text":"CDE reported 4,707 students enrolled in four multi-district online school organizations in 2025–26; one organization operates three schools, explaining the six school-level names in its updated guidance. These are statewide enrollment figures, not Pueblo-only students or displaced students. [S1,S2]"},{"heading":"Homeschool program pathways","text":"CDE initially denied 44 ERBOCES-associated applications after dissolution. The later application review identifies seven programs reapplying under other authorizers and 37 denials attributed to dissolution among 54 unique programs overall. Do not add initial decisions to final categories. [S2,S3]"},{"heading":"Pueblo's separate charter case","text":"On October 16 CDE reported that the State Board remanded the PSAS application to District 60. Its release summarizes D60 concerns regarding location, debt, financial viability, disability services and the online high-school program. Remand is not approval; the later local decision requires verification. [S4]"},{"heading":"What it means for families","text":"Q assessment: continuity of instruction, transportation, special education, records custody and enrollment should be separately checked. CDE advises affected families to contact their own school or program. No individual eligibility or placement is determined here. [S1]"},{"heading":"Follow the funds and future","text":"CDE describes a specialized financial audit and a separate forensic audit scope. Track actual reports, closing balances, receivables, liabilities, contractual obligations, and successor authorization for 2027–28. No audit conclusion or repayment status is inferred. [S1]"}],"unknowns":["No final closing ledger, independent audit outcomes, school-level transition results or later PSAS decision verified.","The original Riverstone funding recovery and ERBOCES aggregate finances must be reconciled separately.","Pueblo-specific counts and 2027–28 permanent authorizations remain unknown."],"sources":[{"id":"S1","title":"CDE — ERBOCES dissolution family guidance, updated October 15","url":"https://ed.cde.state.co.us/erboces-family-info"},{"id":"S2","title":"CDE — emergency online school transfer","url":"https://ed.cde.state.co.us/newsbureau/newsrelease/transfer-online-schools-to-d49"},{"id":"S3","title":"CDE — final 2026–27 homeschool application review","url":"https://ed.cde.state.co.us/choice/homeschool/2026-27-application-review"},{"id":"S4","title":"CDE — October 16 PSAS remand","url":"https://ed.cde.state.co.us/newsbureau/newsrelease/sbe-remands-pueblo-application"}],"keywords":["erboces","school authorizer","pueblo school for the arts and sciences","psas"],"route":"connections.html?issue=case-school-governance"}]};
 for(const story of [{"id":"safe-005","title":"Pueblo courts and detention: workload, capacity and public cost","questions":["Pueblo court and jail workload","How many cases did Pueblo courts receive in FY2024?","What is Pueblo County reporting about the detention center transition?"],"checked":"2026-11-14","reviewBy":"2026-12-14","summary":"The Tenth Judicial District reported 6,767 district-court and 13,205 county-court new filings in FY2024. The county's November 9 dashboard separately identifies new detention facility operations and old facility dormancy as ongoing. Filings are not admissions or unique people. [S1,S2]","chapters":[{"heading":"Scope and workload","text":"The judicial district covers Pueblo County. Its March 2025 summary reports 19,972 new filings in aggregate across district and county court categories. Do not treat this as a backlog, arrest count or incarceration rate. [S1]"},{"heading":"Access and alternatives","text":"The summary describes specialized veterans and behavioral-health courts, probation collaboration and self-help services. Confirm current procedures directly with the judicial branch. [S1,S3]"},{"heading":"Detention transition","text":"The November 9 county dashboard retains August updates for new facility performance and first-year cost tracking under warranty and the old facility's controlled shutdown. [S2]"},{"heading":"Financial stages","text":"The dashboard lists a proposed detention-center solar power purchase agreement as waiting for review, not executed or proven economical. Separate debt, staffing, transport, healthcare and former-facility costs. [S2]"},{"heading":"What would establish results","text":"Compare aggregate occupancy, staffing, transport, timely case disposition, health access and actual expenses against compatible service baselines; these measures have not been established here. Protect individual and juvenile records."},{"heading":"Options and authority","text":"Assess prevention, existing problem-solving courts, staffing, transportation and building efficiency with lawful agencies. No association implies misconduct, and Q provides neither legal advice nor detention decisions."}],"unknowns":["Current occupancy, staffing, court backlogs and actual costs not verified.","No causal link between filings and jail capacity established.","Solar contract terms and savings unresolved."],"sources":[{"id":"S1","title":"Colorado Judicial Branch — Tenth Judicial District Summary, March 2025, p. 1","url":"https://www.coloradojudicial.gov/sites/default/files/2025-04/10_Overview.pdf"},{"id":"S2","title":"Pueblo County — Smart Priorities dashboard, November 9, 2026","url":"https://county.pueblo.org/board-county-commissioners-office/what-we-are-working"},{"id":"S3","title":"Colorado Judicial Branch — Pueblo County court information","url":"https://www.coloradojudicial.gov/courts/trial-courts/pueblo-county/10th-judicial-district"}],"route":"connections.html?issue=safe-005","keywords":["detention center","jail costs","court workload","pueblo courts"]},{"id":"heal-007","title":"Housing instability and homelessness: assistance and dated capacity","questions":["Pueblo housing and homelessness assistance","Where can I find housing help in Pueblo?","What shelter capacity does the 2025 Pueblo housing plan report?"],"checked":"2026-11-14","reviewBy":"2026-12-01","summary":"City resources connect residents to housing, food, health and legal assistance. The 2025–2029 Consolidated Plan, Table 39, lists 96 year-round emergency beds in each of its adult-only and adult-with-children categories. These are dated inventory categories, not vacancies today. [S1,S2,S3]","chapters":[{"heading":"Access and prevention","text":"The city housing guide lists service categories; its Get Help page identifies affordable rentals, vouchers, the Housing Authority and Posada. Confirm eligibility, schedules and availability with providers. [S1,S2]"},{"heading":"Capacity snapshot","text":"Table 39, citing 2025 Balance of State PIT information, also lists 13 transitional beds for adult-only households and permanent supportive beds of 35 for adult-with-child households and nine for adult-only households. These are not current vacant spaces or unduplicated people. [S3]"},{"heading":"Planning and accountability","text":"The city plan describes regional provider coordination and funding support. Grants, commitments, payments and outcomes remain separate evidence stages. [S3]"},{"heading":"Finding help","text":"Use The Pueblo Shelter's service page for overnight shelter information and the city help page for housing and legal referrals. Confirm availability before travel. [S2,S4]"},{"heading":"Evaluate durable results","text":"Compare displacement prevention, accessible affordable housing, supportive services and shelter using time to placement, retention, unmet need and cost. These are proposed measures, not measured outcomes."},{"heading":"Connected issues","text":"Housing, eviction proceedings, healthcare, behavioral health, work, transit and budgets interact. Study these independently and protect sensitive personal records. Association does not establish an individual cause."}],"unknowns":["Current vacancies, eligibility and unduplicated regional demand not verified.","No final expenditure or program outcome audit established.","The 2025 plan table is not a current regional capacity audit."],"sources":[{"id":"S1","title":"City of Pueblo — Housing and Homelessness Guide","url":"https://www.pueblo.us/2949/Housing-and-Homelessness-Guide"},{"id":"S2","title":"City of Pueblo — Get Help","url":"https://www.pueblo.us/3049/Get-Help"},{"id":"S3","title":"City of Pueblo — 2025–2029 Consolidated Plan, Table 39, p. 63","url":"https://www.pueblo.us/DocumentCenter/View/38868/2025-2029-Consolidated-Plan"},{"id":"S4","title":"The Pueblo Shelter — service information","url":"https://www.thepuebloshelter.org/"}],"route":"connections.html?issue=heal-007","keywords":["housing assistance","homelessness","homeless shelter","shelter beds"]}])edition.stories.push(story);
 const expanded={"safe-005":[{"n":1,"title":"What this is about","classification":"Dated source finding","sourceIds":["S1"],"answer":"State court workload in Pueblo County and its distinction from county detention operations."},{"n":2,"title":"The main finding","classification":"Dated source finding","sourceIds":["S1"],"answer":"FY2024 district and county courts recorded 6,767 and 13,205 new filings; the sum is 19,972 filing events, not people."},{"n":3,"title":"How it developed","classification":"Dated source finding","sourceIds":["S1"],"answer":"Behavioral-health court began in 2013 and veterans court in February 2015; courts and probation have occupied the judicial building since August 2014."},{"n":4,"title":"What is happening now","classification":"Not established","sourceIds":[],"answer":"The county dashboard is dated November 9, 2026; current jail occupancy, staffing and court backlogs have not been established."},{"n":5,"title":"Important dates","classification":"Dated source finding","sourceIds":["S1","S2"],"answer":"FY2024 statistical period; March 2025 judicial summary; November 9, 2026 dashboard edition."},{"n":6,"title":"Who is affected","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Court users, victims, defendants, families, jurors, employees and residents may experience different consequences."},{"n":7,"title":"Children and future generations","classification":"Dated source finding","sourceIds":["S1"],"answer":"The district handles juvenile, family and truancy matters. Protect minor records and do not score individual children."},{"n":8,"title":"Families and workers","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Travel, time away from work and childcare can be material access costs; household cost data is absent."},{"n":9,"title":"Neighborhoods and the wider region","classification":"Dated source finding","sourceIds":["S1"],"answer":"The judicial district covers all Pueblo County, including communities outside city boundaries."},{"n":10,"title":"Fairness and access","classification":"Dated source finding","sourceIds":["S1"],"answer":"The building has a self-help center for people handling their own cases; verify present services directly."},{"n":11,"title":"Who is responsible","classification":"Dated source finding","sourceIds":["S1","S2"],"answer":"State courts and county government are distinct authorities; county commissioners set county government priorities."},{"n":12,"title":"Who can make decisions","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Courts decide cases and competent public authorities manage detention and spending under applicable law. Q does not determine outcomes."},{"n":13,"title":"Rules and requirements","classification":"Not established","sourceIds":[],"answer":"Current controlling statutes, court rules, facility procedures and specific case requirements require separate legal verification."},{"n":14,"title":"Promises and commitments","classification":"Not established","sourceIds":[],"answer":"No executed detention service, construction, energy or transport commitment is established by the sources examined here."},{"n":15,"title":"Oversight and accountability","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Compare judicial workload with aggregate dispositions and reconcile county authorizations, contracts, payments and service outcomes."},{"n":16,"title":"Where the money comes from","classification":"Not established","sourceIds":[],"answer":"Funding amounts and applicable revenue sources for these specific court and detention workstreams are not reconciled."},{"n":17,"title":"Costs to the public and households","classification":"Not established","sourceIds":[],"answer":"New and former facility operating costs, medical costs, transport costs and household time costs remain unquantified."},{"n":18,"title":"What has been approved","classification":"Not established","sourceIds":[],"answer":"A dashboard status does not itself establish an approved contract or expenditure."},{"n":19,"title":"What has actually been paid","classification":"Not established","sourceIds":[],"answer":"No payment or audited expense ledger for these workstreams has been reviewed."},{"n":20,"title":"Benefits and value","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Success measures should include lawful treatment, access, timely resolution and safety, not filing volume alone."},{"n":21,"title":"How the service or project works","classification":"Dated source finding","sourceIds":["S1"],"answer":"Trial courts and probation have distinct roles; the summary also identifies specialized problem-solving courts."},{"n":22,"title":"Capacity and availability","classification":"Dated source finding","sourceIds":["S1"],"answer":"March 2025 staffing baseline: eight district judges, three county judges and four magistrates; present staffing is unknown."},{"n":23,"title":"Quality and actual results","classification":"Dated source finding","sourceIds":["S1"],"answer":"FY2024 figures include 789 civil protection orders, 190 described as domestic-abuse-related. Do not equate an order count with unique victims."},{"n":24,"title":"Reliability and maintenance","classification":"Not established","sourceIds":[],"answer":"Facility maintenance, service uptime and actual warranty performance have not been verified."},{"n":25,"title":"Delays and obstacles","classification":"Not established","sourceIds":[],"answer":"No reliable current case delay, detention transfer delay or staffing shortage magnitude established."},{"n":26,"title":"Connections to other issues","classification":"Dated source finding","sourceIds":["S1"],"answer":"Evictions, behavioral health, veterans services, family matters and water cases appear within the court system's documented scope."},{"n":27,"title":"Energy and resource needs","classification":"Not established","sourceIds":[],"answer":"Actual facility electricity, water and energy cost figures or measured solar savings are not established."},{"n":28,"title":"Environmental and physical effects","classification":"Not established","sourceIds":[],"answer":"Physical safety conditions and environmental impacts of facilities have not been independently inspected."},{"n":29,"title":"Risks and unintended effects","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Poorly scoped comparisons could confuse filings with crime or incarceration; public data must exclude sensitive person-level records."},{"n":30,"title":"Long-term consequences","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Long-run outcomes depend on capacity, timely access, lawful services and sustainable operating budgets; no forecast made."},{"n":31,"title":"Available alternatives","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Compare existing specialized courts, appropriate prevention, staffing, transport coordination and facility efficiency."},{"n":32,"title":"Tradeoffs between options","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Capacity expansion may reduce one constraint while adding operating obligations; interventions require lawful authority and outcome evidence."},{"n":33,"title":"Lessons from elsewhere","classification":"Not established","sourceIds":[],"answer":"No comparable external jurisdiction has been evaluated in this specific review."},{"n":34,"title":"What could improve the situation","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Publish comparable quarterly workload, access, backlog and detention operating metrics with definitions and privacy controls."},{"n":35,"title":"What people can do","classification":"Dated source finding","sourceIds":["S1"],"answer":"The March 2025 summary lists the judicial building at 501 N. Elizabeth and court executive telephone 719-404-8700; verify current contact and procedures."},{"n":36,"title":"How strong the evidence is","classification":"Q analysis or practical guidance","sourceIds":["S1","S2"],"answer":"Primary official sources establish dated reported facts, not an independent audit. Dashboard initiative rows were not independently re-extracted in this pass."},{"n":37,"title":"Conflicting information and other explanations","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Filings can rise for procedural or population reasons; no specific explanation or causal link to detention capacity is established."},{"n":38,"title":"What remains unknown","classification":"Not established","sourceIds":[],"answer":"Current occupancy, staffing, dispositions, fiscal actuals and service outcomes remain unresolved."},{"n":39,"title":"What would change the conclusion","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"New official court annual statistics, detention capacity and expense ledgers, and current contracts would update the assessment."},{"n":40,"title":"Qified insight: how the pieces fit together","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Follow court workload and detention performance separately, then connect them through documented procedures, costs and outcomes."}],"heal-007":[{"n":1,"title":"What this is about","classification":"Dated source finding","sourceIds":["S1","S3"],"answer":"Housing stability, homelessness service access and the city's dated facility inventory."},{"n":2,"title":"The main finding","classification":"Dated source finding","sourceIds":["S3"],"answer":"The 2025 plan table reports 96 year-round emergency beds in each adult-only and adult-with-child category; not current vacancies."},{"n":3,"title":"How it developed","classification":"Dated source finding","sourceIds":["S3"],"answer":"The FY2025–2029 plan frames housing, community development and economic opportunities across five years."},{"n":4,"title":"What is happening now","classification":"Not established","sourceIds":[],"answer":"Current shelter availability, waitlists and actual occupancy are not established by the plan or directory."},{"n":5,"title":"Important dates","classification":"Dated source finding","sourceIds":["S3"],"answer":"FY2025–2029 planning horizon; Table 39 uses 2025 Balance of State point-in-time information."},{"n":6,"title":"Who is affected","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"People without stable housing, renters, homeowners, families, service providers and neighborhoods may be affected differently."},{"n":7,"title":"Children and future generations","classification":"Dated source finding","sourceIds":["S3"],"answer":"Table 39 lists 10 voucher/seasonal/overflow beds for unaccompanied youth; these are dated inventory, not open places."},{"n":8,"title":"Families and workers","classification":"Dated source finding","sourceIds":["S1","S2"],"answer":"City resources link housing help with food, health, legal support and employment-related services."},{"n":9,"title":"Neighborhoods and the wider region","classification":"Dated source finding","sourceIds":["S3"],"answer":"City administers CDBG; the City and County participate together in HOME, with distinct program responsibilities."},{"n":10,"title":"Fairness and access","classification":"Dated source finding","sourceIds":["S2"],"answer":"The City lists Colorado Housing Connects as a bilingual information and referral route."},{"n":11,"title":"Who is responsible","classification":"Dated source finding","sourceIds":["S3"],"answer":"Housing and Citizen Services administers the named federal programs; local providers deliver individual services."},{"n":12,"title":"Who can make decisions","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Program administrators and authorized providers determine actual eligibility, intake and awards; Q cannot guarantee placement."},{"n":13,"title":"Rules and requirements","classification":"Not established","sourceIds":[],"answer":"Current grant conditions, tenant rights, provider admissions and individual eligibility require checking applicable rules."},{"n":14,"title":"Promises and commitments","classification":"Dated source finding","sourceIds":["S3"],"answer":"The plan identifies affordability, access and sustainability objectives; objectives are not delivery receipts."},{"n":15,"title":"Oversight and accountability","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Reconcile adopted grant allocations, provider agreements, payments, housing placements and retention using aggregate measures."},{"n":16,"title":"Where the money comes from","classification":"Dated source finding","sourceIds":["S3"],"answer":"The plan identifies CDBG and HOME as funding streams; current balances and individual program awards are not established."},{"n":17,"title":"Costs to the public and households","classification":"Not established","sourceIds":[],"answer":"Household rent burden, program unit costs and total regional homelessness-related expenses are not reconciled."},{"n":18,"title":"What has been approved","classification":"Not established","sourceIds":[],"answer":"Final funding authorization for each named provider is not established by the planning document."},{"n":19,"title":"What has actually been paid","classification":"Not established","sourceIds":[],"answer":"No current grant drawdowns, reimbursements or provider payment ledger reconciled."},{"n":20,"title":"Benefits and value","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Measure sustained housing, prevention of displacement, access and safety instead of treating one-time placement as durable success."},{"n":21,"title":"How the service or project works","classification":"Dated source finding","sourceIds":["S2"],"answer":"The City's resource page identifies affordable rentals, vouchers and provider referrals."},{"n":22,"title":"Capacity and availability","classification":"Dated source finding","sourceIds":["S3"],"answer":"Table 39 lists 13 transitional beds for adult-only households, 35 permanent supportive beds for adult-with-child and nine for adult-only."},{"n":23,"title":"Quality and actual results","classification":"Not established","sourceIds":[],"answer":"No verified rates for retention, completed referrals, service quality or unmet need in this review."},{"n":24,"title":"Reliability and maintenance","classification":"Not established","sourceIds":[],"answer":"Current shelter operating continuity, building condition and maintenance needs are not established."},{"n":25,"title":"Delays and obstacles","classification":"Dated source finding","sourceIds":["S3"],"answer":"The city plan identifies transport access as a barrier reported by stakeholders; its current magnitude is unknown."},{"n":26,"title":"Connections to other issues","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Housing is connected to eviction courts, healthcare, behavioral health, food, work, transit and public funding; association is not causation."},{"n":27,"title":"Energy and resource needs","classification":"Not established","sourceIds":[],"answer":"Building energy, heating, water and service resource costs are not separately quantified."},{"n":28,"title":"Environmental and physical effects","classification":"Not established","sourceIds":[],"answer":"Environmental hazards, site-specific conditions and physical accessibility require current inspection evidence."},{"n":29,"title":"Risks and unintended effects","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Do not double count provider listings, bed categories or displaced households; protect client and child identities."},{"n":30,"title":"Long-term consequences","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Prevention and stable occupancy could reduce repeat displacement, but long-term effect size needs observed evidence."},{"n":31,"title":"Available alternatives","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Compare prevention, rental assistance, affordable development, emergency shelter and supportive housing."},{"n":32,"title":"Tradeoffs between options","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Emergency shelter addresses immediate need; affordable and supportive housing may address longer-term needs but require funding, capacity and coordination."},{"n":33,"title":"Lessons from elsewhere","classification":"Not established","sourceIds":[],"answer":"No comparative external program outcome study was established for this report."},{"n":34,"title":"What could improve the situation","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Use a common dated inventory of available services, capacity, outcomes and funding stages with privacy-preserving referral routes."},{"n":35,"title":"What people can do","classification":"Dated source finding","sourceIds":["S2"],"answer":"The City's Get Help page lists Housing Authority 719-542-6741, Posada 719-545-8776 and Colorado Housing Connects 1-844-926-6632. Confirm hours and availability."},{"n":36,"title":"How strong the evidence is","classification":"Q analysis or practical guidance","sourceIds":["S1","S2","S3"],"answer":"Official city pages and the plan support dated descriptions; a plan is not proof of current service performance."},{"n":37,"title":"Conflicting information and other explanations","classification":"Q analysis or practical guidance","sourceIds":["S3"],"answer":"Table 39 and provider descriptions use different categories and units; reconcile them before totaling. A zero in a table row is not proof no person needs help."},{"n":38,"title":"What remains unknown","classification":"Not established","sourceIds":[],"answer":"Current inventory, vacancies, unduplicated need, spending, retention and service disruptions remain unknown."},{"n":39,"title":"What would change the conclusion","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Updated operator-confirmed inventory, audited grant expenditures, current waitlist and aggregate housing outcomes would change the assessment."},{"n":40,"title":"Qified insight: how the pieces fit together","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Connect immediate help to durable prevention and evidence of actual housing stability, not merely counts of beds or dollars planned."}]};
 for(const s of edition.stories)if(expanded[s.id])s.coverage40=expanded[s.id];
 const priorityStories=[{"id":"qp-fin-council-53001","title":"Does Pueblo City Council really have $100,000 for independent legal advice?","checked":"2026-11-17","reviewBy":"2026-11-23","route":"council-attorney-funding.html","questions":["Does Pueblo City Council have $100,000 for an attorney?","Pueblo City Council attorney funding","What is in Council account 53001?"],"keywords":["council attorney","independent counsel","53001","professional services"],"summary":"Pueblo's adopted 2026 budget lists $221,000 for Council professional services, not a separately identified $100,000 attorney line on page D-5. A 2019 procurement sought independent legal advice. The submitted $100,000 claim, current account balance, audit and lobbying charges and availability of counsel funds still need ledger-level confirmation. [S1,S2]","sources":[{"id":"S1","title":"City of Pueblo 2026 adopted budget, printed D-5 (PDF page 34)","url":"https://www.pueblo.us/ArchiveCenter/ViewFile/Item/5351"},{"id":"S2","title":"City RFQ 19-016 — part-time independent legal advice (2019)","url":"https://www.pueblo.us/bids.aspx?PRINT=YES&bidID=683"},{"id":"S3","title":"Pueblo Ledger — November 14, 2026 proposed city and county budgets and hearings","url":"https://puebloledger.com/government-watch/pueblo-2027-budgets-city-county/"},{"id":"S4","title":"City Finance Department — budget and financial reporting","url":"https://www.pueblo.us/92/Finance"},{"id":"S5","title":"City Purchasing — procurement","url":"https://www.pueblo.us/105/Purchasing"}],"chapters":[{"kind":"context","heading":"A line in a budget is not money in reserve","text":"Imagine setting aside money for a lawyer in a household account that also pays an accountant. The balance alone cannot tell you what is available once existing bills come due. Council's $100,000 claim raises the same accounting question; it is not proof of missing funds."},{"kind":"money","heading":"What the official table shows","text":"Account 53001 totals $181,000 in 2023 actuals, $185,183 in 2024 actuals, $184,661 in 2025 projected actuals, and $221,000 in the 2026 adopted budget. Total FY2026 Council expenses budgeted: $503,082. An adopted budget is not a payment ledger. [S1]"},{"kind":"chronology","heading":"A longstanding need","text":"In February 2019 the City sought qualifications for independent Council legal advice in cases of an actual or perceived conflict involving the City Attorney. The closed solicitation does not establish an award, an ongoing engagement or current funding. [S2]"},{"kind":"people","heading":"Who can resolve it","text":"Council can ask for a reconciled schedule; Finance holds accounting records, Purchasing holds procurement records, and the Clerk holds legislative records. Ask the Mayor and Finance Director for the precise budget and transaction reconciliation, not assumptions about intent. [S4,S5]"},{"kind":"options","heading":"Three ways to improve oversight","text":"Separate audit, lobbying and counsel in a public purpose-level schedule; compare an on-call agreement with dedicated counsel; require a monthly adopted-to-amended-to-actual-to-committed reconciliation. An illustrative $100,000 cap buys 400 hours at $250 per hour before other costs, not a local quote."},{"kind":"future","heading":"Before the next budget vote","text":"The Pueblo Ledger reports a November 23, 2026 city budget hearing at 5:30 p.m. Verify the official agenda before attending. Ask for the FY2026 account roll-forward and FY2027 purpose-specific allocation. [S3]"},{"kind":"meaning","heading":"Qified: public oversight is a capacity, not just a line item","text":"Budget clarity, independent legal advice, financial review and transparent AI procurement reinforce one another. Preserve lawful human authority, protect privileged records, and track consequences for services and future generations."}],"unknowns":["Current amended appropriation, expenditures, commitments and genuinely available amount.","Whether audit and lobbying are charged to this account, and the amount of each.","The original $100,000 allocation record and latest meeting transcript; no finding of unlawful diversion or misconduct.","FY2027 final allocation and procurement outcome."],"coverage40":[{"n":1,"title":"Scope","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"City of Pueblo Council professional services, not county or all city legal spending."},{"n":2,"title":"Central question","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Determine whether Council can actually retain independent counsel within lawful available resources."},{"n":3,"title":"Submitted claim","classification":"Not established","sourceIds":[],"answer":"The assertion of a recurring $100,000 allocation and nothing remaining is not yet substantiated by a reconciled ledger."},{"n":4,"title":"2023 actual","classification":"Dated source finding","sourceIds":["S1"],"answer":"The adopted 2026 book lists $181,000 actual professional services in 2023."},{"n":5,"title":"2024 actual","classification":"Dated source finding","sourceIds":["S1"],"answer":"The same table lists $185,183 actual professional services in 2024."},{"n":6,"title":"2025 projection","classification":"Dated source finding","sourceIds":["S1"],"answer":"The table lists $184,661 as projected actuals, not audited final expenditures."},{"n":7,"title":"2026 authority","classification":"Dated source finding","sourceIds":["S1"],"answer":"The adopted budget lists $221,000 under Council account 53001."},{"n":8,"title":"Council total","classification":"Dated source finding","sourceIds":["S1"],"answer":"The adopted FY2026 total for Council expenses is $503,082."},{"n":9,"title":"Historical procurement","classification":"Dated source finding","sourceIds":["S2"],"answer":"The February 2019 RFQ sought independent legal advice where a conflict was perceived or actual."},{"n":10,"title":"Award history","classification":"Not established","sourceIds":[],"answer":"An award, later engagement or cancellation has not been confirmed."},{"n":11,"title":"Funding purpose","classification":"Not established","sourceIds":[],"answer":"The original instrument establishing the reported attorney allocation is needed."},{"n":12,"title":"Audit charges","classification":"Not established","sourceIds":[],"answer":"No vendor-by-vendor allocation to Council's audit costs verified in this review."},{"n":13,"title":"Lobbying charges","classification":"Not established","sourceIds":[],"answer":"No contract or ledger confirming the claimed lobbying account charges reviewed."},{"n":14,"title":"Current balance","classification":"Not established","sourceIds":[],"answer":"Current amended appropriation and transaction detail have not been obtained."},{"n":15,"title":"Commitments","classification":"Not established","sourceIds":[],"answer":"Open purchase orders and contractual obligations remain unverified."},{"n":16,"title":"Discretionary funds","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Subtract non-overlapping recognized expenditures, open commitments and necessary remaining obligations from legally usable authority."},{"n":17,"title":"Budget stage","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Separate requested, proposed, adopted, amended, committed, expended and cash-paid states."},{"n":18,"title":"Reserve use","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Determine whether recurring expenditures depend on one-time reserves; a reserve draw alone does not prove illegality."},{"n":19,"title":"Financial scenario","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"If $221,000 were amended authority and $180,000 were committed or spent, only $41,000 would remain before other obligations; illustrative only."},{"n":20,"title":"Authority","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Confirm charter, ordinances, delegation and conflicts with legal counsel before assigning decision rights."},{"n":21,"title":"Finance role","classification":"Dated source finding","sourceIds":["S4"],"answer":"The city's Finance Department provides the official financial reporting and budget source hub."},{"n":22,"title":"Procurement role","classification":"Dated source finding","sourceIds":["S5"],"answer":"The city identifies its electronic procurement system as the route for solicitations and vendor management."},{"n":23,"title":"Administrative explanation","classification":"Not established","sourceIds":[],"answer":"Review the complete meeting recording and written answers before characterizing officials' explanations."},{"n":24,"title":"Counterevidence","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"A broad account may legitimately include several services; a shared code does not prove diversion."},{"n":25,"title":"Independent audit","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"An audit opinion and a decision-ready current budget reconciliation answer different questions."},{"n":26,"title":"Residents","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Make the same account crosswalk accessible to taxpayers and elected officials."},{"n":27,"title":"Child impact","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Trace any service reductions to verified program decisions; no direct child harm established."},{"n":28,"title":"Equity","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Use plain-language, accessible public tables rather than requiring specialized accounting knowledge."},{"n":29,"title":"Worker impact","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Do not count vacant positions as sustainable savings without testing effects on workload and services."},{"n":30,"title":"Option A","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Publish a purpose-level reconciliation using existing accounting exports before buying software."},{"n":31,"title":"Option B","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Separate legal, audit and lobbying reporting codes while preserving lawful procurement."},{"n":32,"title":"Option C","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Compare part-time or on-call legal counsel with dedicated capacity and conflict procedures."},{"n":33,"title":"Cost example","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"A $100,000 illustrative cap at $250 per hour provides 400 hours before other costs; obtain actual bids."},{"n":34,"title":"EE","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Measure staff reconciliation time, external review costs and decision error avoided against a manual baseline."},{"n":35,"title":"T2Y","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Truth requires the appropriation and ledger; useful yield is an understandable decision-ready schedule."},{"n":36,"title":"Digital twin and shadow","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Represent only verified finance states; simulate potential obligations separately without silently overwriting the ledger."},{"n":37,"title":"Event horizons","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Before FY2027 adoption seek the reconciliation; quarterly monitor obligations; over five years assess structural oversight capacity."},{"n":38,"title":"Records request","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Request account 53001 detail, contracts, purchase orders, amendments and attorney procurement records for 2019 through present; protect exempt material."},{"n":39,"title":"Reopen conditions","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Recheck on new ledger, meeting transcript, final budget, procurement award or correction; historical figures remain intact."},{"n":40,"title":"Qified synthesis","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Independent oversight needs understandable finance, legally available resources and human decision authority; link to AI governance and all major public spending reviews."}]},{"id":"qp-reg-ai-readiness","title":"Is Pueblo ready for the AI era? A regional plan for people, jobs and public services","checked":"2026-11-17","reviewBy":"2026-12-17","route":"pueblo-ai-readiness.html","questions":["Is Pueblo ready for the AI era?","Is the Pueblo region ready for AI?","Pueblo AI readiness","How can Pueblo prepare for AI?"],"keywords":["ai readiness","ai era","artificial intelligence","regional ai","ai workforce"],"summary":"Pueblo has credible starting assets: college AI and technical education, public library technology assistance, workforce services and 89.1% household broadband subscription in Pueblo County (2020–2024). These do not establish region-wide operational readiness. A coordinated, fiscally bounded, human-governed transition is the recommended next step. [S1–S6]","sources":[{"id":"S1","title":"US Census QuickFacts — Pueblo County, 2020–2024 broadband and computer subscriptions","url":"https://www.census.gov/quickfacts/fact/table/pueblocountycolorado/INT100224"},{"id":"S2","title":"Pueblo Community College — AI-enhanced education and Southern Colorado AI event","url":"https://pueblocc.edu/SoCO-AI"},{"id":"S3","title":"CSU Pueblo — CIS concentrations including data analytics and AI","url":"https://www.csupueblo.edu/computer-information-systems/concentration-areas.html"},{"id":"S4","title":"Pueblo City-County Library — technology assistance and makerspaces","url":"https://www.pueblolibrary.org/"},{"id":"S5","title":"Pueblo Workforce Center — job seeker and employer services","url":"https://county.pueblo.org/human-services-department/colorado-workforce-center"},{"id":"S6","title":"PCC cybersecurity program","url":"https://pueblocc.edu/Programs/CSE"},{"id":"S7","title":"Colorado Attorney General — ADMT and chatbot safety law and rulemaking","url":"https://coag.gov/ai/"},{"id":"S8","title":"NIST AI Risk Management Framework Core","url":"https://airc.nist.gov/airmf-resources/airmf/5-sec-core/"},{"id":"S9","title":"Colorado OIT — statewide GenAI strategy and reported results","url":"https://oit.nxt-dev.colorado.gov/standards-policies-guides/guide-to-artificial-intelligence/explore-colorados-statewide-genai"},{"id":"S10","title":"San José AI policy and guidelines","url":"https://www.sanjoseca.gov/your-government/departments-offices/information-technology/itd-generative-ai-guideline"},{"id":"S11","title":"Government AI Coalition — reusable templates and resources","url":"https://www.sanjoseca.gov/your-government/departments-offices/information-technology/artificial-intelligence-inventory/govai-coalition/templates-resources"},{"id":"S12","title":"Colorado OEDIT — Pueblo regional industry clusters","url":"https://choosecolorado.com/regional-profile/pueblo-region/"}],"chapters":[{"kind":"context","heading":"The next industrial transition is already here","text":"AI is software that identifies patterns, generates content or assists decisions. It can help a machinist interpret a manual, a clerk locate a public record, or a small business draft a quote. It can also fabricate a fact, leak a record or exclude residents. AI readiness is the ability to use it well and say no when it is not appropriate. It is not the same as building a data center."},{"kind":"people","heading":"Pueblo is not starting from zero","text":"In 2020–2024, 89.1% of Pueblo County households subscribed to broadband, and 94.9% had a computer. PCC advertised a no-cost Southern Colorado AI event, CSU Pueblo teaches data analytics and AI-related topics, PCC offers cybersecurity, the library offers technology help and the Workforce Center offers job and employer services. These are assets, not proof every resident is ready. [S1–S6]"},{"kind":"meaning","heading":"What this means for everyday Pueblo","text":"A family can use a library workshop to learn how to spot scams; a shop can compare AI-assisted quotes with actual costs; a public works crew can test maintenance summaries without allowing AI to control machinery; a resident can locate a dated ordinance with its source. These are proposed local pilots, not claims of existing deployment. Manufacturing, health, transport and infrastructure are documented regional industry clusters. [S12]"},{"kind":"context","heading":"What real governments are doing","text":"Colorado OIT reports 6,447 trained state users of Gemini as of May 2026, alongside risk review and human supervision. San José requires privacy and fairness review, staff accountability and approval before acquisition; its coalition provides reusable templates. These examples demonstrate a route to learn from, not a promise of equal savings in Pueblo. [S9–S11]"},{"kind":"money","heading":"What might it cost?","text":"Illustrative year-one regional scenarios, not bids or appropriations: $50,000 lean discovery and pilot (coordination $15k, training $10k, security/legal $10k, tools $5k, evaluation $5k, contingency $5k); $250,000 shared pilot (staff $100k, training $40k, tools/data $35k, cybersecurity/legal $35k, access support $20k, evaluation $10k, contingency $10k); $750,000 regional scale (staff $300k, training $140k, access $75k, data/tools $90k, security/legal $70k, evaluation $35k, contingency $40k). Recurring costs and local procurement quotes must be developed before funding; no data-center capital included."},{"kind":"options","heading":"How to proceed without sacrificing services","text":"Within 30 days, convene voluntary partners and inventory systems, skills and contracts. By 90 days, adopt a policy and select low-risk pilots with measured manual baselines. In 6–12 months, publish evaluated benefits, defects and costs before scaling. Do not redirect restricted funds or assume staff time saved is cash recovered."},{"kind":"future","heading":"Who, where and when","text":"Suggested conveners are City and County leadership, PCC, CSU Pueblo, library, workforce center, school districts, employers, utilities, residents and independent counsel. Start in existing facilities, including libraries and classrooms; cover Pueblo West, rural communities and residents without home broadband. Colorado's new ADMT and chatbot safety provisions generally take effect January 1, 2027; determine specific applicability with counsel and follow the rulemaking. [S7]"},{"kind":"meaning","heading":"Qified: a region ready for AI is ready to govern it","text":"Use the NIST govern/map/measure/manage process, public accountability, independent review, child safeguards, manual alternatives, incident response and shutdown. Connect literacy, economic transition, public finance, cyber resilience, accessibility, energy, water and democratic oversight. [S8]"}],"unknowns":["No comprehensive regional AI asset, spending, vendor or risk inventory reviewed.","No verified workforce adoption, job displacement forecast, school policies, local procurement bids or measured local productivity outcomes.","No confirmed multi-entity governance commitment, broadband affordability breakdown or engineering capacity for new compute facilities.","No local program or funding in the scenarios has been approved."],"coverage40":[{"n":1,"title":"Scope","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Pueblo County is the quantitative baseline; nearby Southern Colorado partners may join voluntarily, with boundaries explicit."},{"n":2,"title":"What AI means","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Models can generate, classify, predict or recommend; they are not reliable authorities and can produce confident errors."},{"n":3,"title":"Readiness conclusion","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Starting assets exist but operational readiness across institutions is not established; readiness must be measured by capability."},{"n":4,"title":"Population","classification":"Dated source finding","sourceIds":["S1"],"answer":"Census QuickFacts estimates 169,277 Pueblo County residents on July 1, 2025."},{"n":5,"title":"Internet access","classification":"Dated source finding","sourceIds":["S1"],"answer":"89.1 percent of county households subscribed to broadband in 2020–2024; 10.9 percent did not."},{"n":6,"title":"Device access","classification":"Dated source finding","sourceIds":["S1"],"answer":"94.9 percent of county households had a computer in 2020–2024; this does not measure AI literacy."},{"n":7,"title":"PCC","classification":"Dated source finding","sourceIds":["S2"],"answer":"PCC advertised a free Southern Colorado AI event with ethics, applied tools and AI-at-work sessions."},{"n":8,"title":"CSU Pueblo","classification":"Dated source finding","sourceIds":["S3"],"answer":"The CIS data analytics concentration includes AI, cloud computing and deep learning."},{"n":9,"title":"Cyber education","classification":"Dated source finding","sourceIds":["S6"],"answer":"PCC advertises dedicated cybersecurity labs and certificates in defense and networking."},{"n":10,"title":"Library","classification":"Dated source finding","sourceIds":["S4"],"answer":"The public library advertises free technology assistance and makerspaces."},{"n":11,"title":"Workforce services","classification":"Dated source finding","sourceIds":["S5"],"answer":"The local Workforce Center provides training, skills assessments and employer services."},{"n":12,"title":"Local economy","classification":"Dated source finding","sourceIds":["S12"],"answer":"The state regional profile identifies health, advanced manufacturing, infrastructure and logistics clusters."},{"n":13,"title":"Jobs and tasks","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Inventory tasks likely to change; train workers in checking output, domain knowledge and safe methods; do not equate task exposure with job loss."},{"n":14,"title":"Small business","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Pilot quotes, inventory summaries and marketing drafts using redacted data; verify prices and actual profit margins."},{"n":15,"title":"Manufacturing","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Test document retrieval and maintenance triage offline; qualified staff retain equipment control and safety approvals."},{"n":16,"title":"Healthcare","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Start with nonclinical administrative material; protect health information and require professional review; no automated diagnoses."},{"n":17,"title":"Agriculture","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Evaluate greenhouse and irrigation monitoring against conventional sensors; never infer local water savings without measurement."},{"n":18,"title":"Government","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Start with public-record search and draft summaries, not automated policing, benefits, permits or hiring decisions."},{"n":19,"title":"Education","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Teach verification, citation, bias, privacy and when not to use AI; keep assessments developmentally appropriate."},{"n":20,"title":"Child protection","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"No child profiling, undisclosed chatbot use or dependence design; establish adult support, reporting and non-AI access."},{"n":21,"title":"Senior and disability access","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Provide accessible in-person help, plain language, Spanish options and telephone alternatives; test with users."},{"n":22,"title":"Rural inclusion","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Map connectivity, affordability and travel barriers before selecting sites; include Pueblo West and outlying communities."},{"n":23,"title":"Colorado law","classification":"Dated source finding","sourceIds":["S7"],"answer":"The Attorney General describes SB 26-189 and HB 26-1263 as effective January 1, 2027; confirm applicability and final rules."},{"n":24,"title":"Risk framework","classification":"Dated source finding","sourceIds":["S8"],"answer":"NIST organizes risk work around govern, map, measure and manage, continuously across the lifecycle."},{"n":25,"title":"Real-life Colorado example","classification":"Dated source finding","sourceIds":["S9"],"answer":"OIT reports 6,447 trained Gemini users by May 2026 and a risk-based approach with human oversight."},{"n":26,"title":"Real-life San José example","classification":"Dated source finding","sourceIds":["S10","S11"],"answer":"San José publishes AI purchasing and safety guidelines; its coalition shares implementation templates."},{"n":27,"title":"Funding model","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Seek lawful partner contributions and eligible grants, verify matching requirements and prohibit reliance on uncertain awards."},{"n":28,"title":"Lean pilot cost","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Illustrative $50k first year: coordination 15k, training 10k, security/legal 10k, tools 5k, evaluation 5k, contingency 5k."},{"n":29,"title":"Shared pilot cost","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Illustrative $250k: staff 100k, training 40k, tools/data 35k, security/legal 35k, access 20k, evaluation 10k, contingency 10k."},{"n":30,"title":"Scale cost","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Illustrative $750k: staff 300k, training 140k, access 75k, data/tools 90k, security/legal 70k, evaluation 35k, contingency 40k."},{"n":31,"title":"Energy and water","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Use existing hosted services first if appropriate; any local compute build requires verified grid, water, cooling, emissions and lifecycle analysis."},{"n":32,"title":"Data governance","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Inventory datasets, permissions, provenance, retention, accessibility and vendor training restrictions; never enter protected records into unapproved tools."},{"n":33,"title":"Procedure and procurement","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Define need, compare non-AI baseline, risk tier, legal review, security test, competitive purchasing, pilot, human approval and rollback."},{"n":34,"title":"Evaluation and EE","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Measure quality-adjusted hours and cost per accepted outcome, including training, review, errors, cybersecurity and compute; no savings asserted."},{"n":35,"title":"T2Y","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Measure source accuracy, public usefulness and correct referrals; return unknowns rather than inventing answers."},{"n":36,"title":"Twin and shadow","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Map verified institutions and resource states in the twin; maintain reversible scenarios in the shadow model, not a live control system."},{"n":37,"title":"Event horizons and LEAP","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"30 days inventory; 90 days pilot; 6–12 months evaluation; two years scale only if justified; five years monitor job and infrastructure transitions."},{"n":38,"title":"Accountability and RX","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Publish inventory, owners, limitations and incidents; enable human appeals, corrections, exit and fallback; version evidence and revalidate."},{"n":39,"title":"Evidence gaps","classification":"Not established","sourceIds":[],"answer":"No complete regional readiness inventory, adoption survey, cost quotes, outcome tests or approved joint program is established."},{"n":40,"title":"Qified synthesis","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Make AI a regional literacy, workforce, governance and resilience initiative rather than a hardware purchase; connect public finance, child safety, industrial transition, water, energy and access."}]}];
 const regionalStories=[{"id":"qp-county-disclosure-2026","title":"Where are Pueblo County’s 2025 financial records?","route":"county-financial-transparency.html","checked":"2026-11-18","reviewBy":"2026-12-02","questions":["Where is Pueblo County's 2025 ACFR?","Where are Pueblo County's 2025 salary records?","Is Pueblo County financially transparent?"],"keywords":["county transparency","2025 salary disclosure","financial reporting","missing acfr"],"summary":"The county salary and ACFR archives both end in 2024 on November 18. Missing web publications are documented accessibility gaps, not proof that salary notices were never published or that the state never received an audit. [S1,S2]","chapters":[{"heading":"Dated public observation","text":"The financial archive lists 2012–2024 (13 annual reports); salary archive lists 2017–2024 (eight). The salary page retains an introductory notice referring to 2020. Neither archive shows its 2025 annual document. The user supplied six screenshots consistent with these observations. [S1,S2]","kind":"context"},{"heading":"Public accessibility versus legal compliance","text":"C.R.S. 30-25-111 requires salary information in February for the previous calendar year and August for the previous June. The publication mechanism is normally a legal newspaper. It also covers monthly paid claims and contracts and semiannual treasurer statements. A missing website link does not prove nonpublication in a newspaper. [S3]","kind":"context"},{"heading":"Audit deadline","text":"For December year-end governments, the audit normally reaches the entity by June 30 and the state by July 31, or a filing-extension request is due by July 31. The state has delinquency and potential tax-withholding processes. Do not infer an extension or enforcement outcome from a website gap. [S4]","kind":"context"},{"heading":"County's own explanation","text":"The county reports additional accounting work approved September 29, draft statements in the second half of October and audit fieldwork the week of October 26. A dashboard status is not a signed audit opinion or a state filing receipt. [S5]","kind":"context"},{"heading":"Community signal","text":"A supplied social-media post questioned the missing files and commissioner pay during proposed workforce cuts. Four subsequent images show six distinct visible comments, one partial. Themes include distrust, pay equity, deputy staffing, hiring barriers and retirement eligibility. Nine shares were visible; comments were filtered. This is a qualitative signal, not representative sentiment. No names, profile images or insulting claims are republished.","kind":"context"},{"heading":"Comparison and alternatives","text":"Douglas County offers year-end 2025 and June 2026 disclosures on its payroll page. Use the comparable disclosure cadence as a practical benchmark, not a rank of all counties. [S6]","kind":"context"},{"heading":"Audit processing","text":"Inventory each statutory record by entity, fiscal period, due date, channel, original URL, retrieval date and evidence status. Compare archived versions and search state repositories, public newspaper notices and meeting packets before filing requests. Record absent on checked page separately from not published anywhere.","kind":"options"},{"heading":"Accountability","text":"Commissioners set oversight expectations; finance prepares accounting information; the treasurer maintains fund information; the state auditor oversees filing. The independent CPA evaluates evidence; duties must not be assigned to individuals solely because of their job titles.","kind":"context"},{"heading":"Impact and child lens","text":"Late public information limits independent review of workforce and service decisions. Housing insecurity, family finances and emergency response effects are possible downstream risks, not outcomes demonstrated by these records.","kind":"context"},{"heading":"EE / LL / T2Y","text":"Reuse archives and law links across all financial investigations; retain the first recorded absence and later publication dates. Calculate repeated search time and rework instead of assuming savings. Preserve the difference between document date, as-of date and date observed.","kind":"options"},{"heading":"RX and leap gate","text":"Publish a dated disclosure calendar plus human-readable and CSV/JSON exports. For each item show not due, found, late against normal date, extension verified or not located. Never silently overwrite a past observation. Human review is required before changing a status to violation.","kind":"options"},{"heading":"Event horizons","text":"Recheck during December 2026 budget deliberations, in February 2027 for 2026 annual payroll, and August 2027 for June payroll. Follow the next annual audit cycle, then compare on-time performance in 2029 and 2031. These are Q review milestones, not county commitments.","kind":"options"}],"unknowns":["Legal newspaper publication dates and copies not located in this review.","2025 independent opinion and state filing/extension status not verified.","Complete monthly claims and semiannual publication series not reconciled."],"sources":[{"id":"S1","title":"County annual financial reports — archive","url":"https://county.pueblo.org/budget-and-finance-department/annual-comprehensive-financial-report-acfr"},{"id":"S2","title":"County salary disclosures — archive","url":"https://county.pueblo.org/budget-and-finance-department/pueblo-county-salaries"},{"id":"S3","title":"Colorado statutory text §30-25-111 (public law reproduction)","url":"https://colorado.public.law/statutes/crs_30-25-111"},{"id":"S4","title":"Office of State Auditor filing calendar","url":"https://content.leg.colorado.gov/agencies/office-state-auditor/calendars-and-due-dates"},{"id":"S5","title":"County priorities dashboard — November 2026","url":"https://county.pueblo.org/board-county-commissioners-office/what-we-are-working"},{"id":"S6","title":"Douglas County payroll disclosure example","url":"https://www.douglasco.gov/finance/payroll/"}],"packet":{"schemaVersion":"1.0","lifecycle":"active","publicationStatus":"partial","evidenceStatus":"dated public-source review; some analysis and secondary reports","reviewDue":"2026-12-02","related":["qp-county-compensation-2026","qp-county-audit-cost-2026","qp-regional-fragmentation-2026"],"build":"Disclosure calendar; status vocabulary; public-source intake; archived observations. No automated monitoring is enabled.","privacy":"No commenter names or screenshots reproduced","validation":"Public-source arithmetic and source attribution; no certified audit"}},{"id":"qp-county-compensation-2026","title":"Who sets commissioner pay — and how does it compare with county workers?","route":"county-commissioner-compensation.html","checked":"2026-11-18","reviewBy":"2026-12-02","questions":["Who sets Pueblo County commissioner salaries?","Are all Pueblo County commissioners paid $158,669?","How much do Pueblo County commissioners make?"],"keywords":["commissioner salary","county salaries","pay increases","compensation equity","county worker"],"summary":"The 2024 publication lists $131,700, $125,916 and $131,700. The state schedule assigns Pueblo Category I-A, with $158,669 annually for new terms starting in 2026–27, not every incumbent’s verified payroll. [S1,S2]","chapters":[{"heading":"What the original payroll publication says","text":"The three listed commissioner rows total $389,316. The same page lists county manager $221,460, county attorney $180,000 and several different administrator rates. These are published salary entries, not independently reconciled payroll or benefits. [S1]","kind":"context"},{"heading":"Who establishes the rate","text":"Colorado's elected county official salary framework under C.R.S. 30-2-102 applies category and term-specific schedules. The September 2026 state memo includes Pueblo in I-A and sets $158,669 for commissioners whose terms begin in 2026 or 2027. Generally compensation cannot change during an elected term, subject to applicable legal provisions. [S2]","kind":"context"},{"heading":"Recalculate the social-media claim","text":"$158,669 minus $131,700 equals $26,969 (20.48%); compared with $125,916 the difference is $32,753 (26.01%). These compare different published rates/periods; neither proves that all three current commissioners received the same raise or personally voted for it. [S1,S2]","kind":"context"},{"heading":"Comparable state rates","text":"Table 1 also lists Category I-A sheriff $201,926 and treasurer, assessor and clerk $158,669 for the relevant new terms. Avoid treating all officials as already being paid the new rate. [S2]","kind":"context"},{"heading":"Household comparison","text":"$158,669 is 3.17 times a hypothetical $50,000 annual wage. Three such commissioner salaries would total $476,007 before benefits, a scenario not current payroll. Compared with the 2024 listed total, the difference would be $86,691, not a measure of lawful savings. [S1,S2]","kind":"context"},{"heading":"Compensation versus funding","text":"The preliminary budget identifies department reduction targets, not individual wage reductions. The elected office may meet its target in different spending categories. Compare authorized compensation, funded position, actual salary, overtime, employer benefit and vacancy separately. [S5]","kind":"context"},{"heading":"Counterpoint","text":"Local affordability is a valid public-policy question even when the statutory rate is set by the state. The compensation mechanism, board's local budget decisions and actual employee treatment are different questions.","kind":"context"},{"heading":"Community signal","text":"Visible responses include concerns about executive compensation, deputy safety, ability to afford taxes and a self-reported difficulty obtaining county employment. The hiring account is unverified; no conclusion about discrimination, intent or personal enrichment follows.","kind":"context"},{"heading":"Hiring and benefits","text":"Analyze public job postings, pay bands, eligibility, vacancies, selection rules and aggregate retention before judging hiring fairness. Compare pension participation using plan documents and aggregate contributions; never infer individual enrollment or disclose protected records.","kind":"context"},{"heading":"Child and economic impacts","text":"Model changes in household income, childcare affordability and spending at local businesses if workforce reductions occur; distinguish positions from people and authorized from actual reductions.","kind":"context"},{"heading":"Q processing and build","text":"Use year, title, appointment/term start, salary basis, benefit basis, fund, source and confidence. Make term schedules a separate dataset joined to office positions only when effective-date evidence is known. Public view must not identify private employees beyond authorized disclosures.","kind":"options"},{"heading":"EE / T2Y / LL","text":"Calculate changes once from preserved source rows; compare similarly scoped compensation across years and institutions. Avoid repeating the viral claim as verified. Retain the original concern as a public-signal record.","kind":"options"},{"heading":"RX and horizons","text":"Verify 2025/2026 public disclosures, the applicable effective rate for each office and February 2027 reporting. For 2029 and 2031 assess affordability against comparable workloads and local wage distributions, not arbitrary executive-pay ceilings.","kind":"options"}],"unknowns":["Individual 2025 and 2026 payroll and effective term dates not reconciled.","Individual pension participation and fringe benefit amounts unresolved.","Hiring allegation not independently investigated."],"sources":[{"id":"S1","title":"2024 county salary publication — PDF page 1","url":"https://county.pueblo.org/sites/default/files/2025-01/DEC%202024%20to%20Newspaper.pdf"},{"id":"S2","title":"Legislative Council Staff — September 14, 2026 memo, table 1 page 4","url":"https://content.leg.colorado.gov/publications/2026-and-2027-salaries-elected-county-officials"},{"id":"S3","title":"County salary archive","url":"https://county.pueblo.org/budget-and-finance-department/pueblo-county-salaries"},{"id":"S4","title":"Colorado salary publication statute","url":"https://colorado.public.law/statutes/crs_30-25-111"},{"id":"S5","title":"County's proposed 2027 budget presentation","url":"https://county.pueblo.org/sites/default/files/2026-10/2027%20Proposed%20Budget%20SB.pdf"}],"packet":{"schemaVersion":"1.0","lifecycle":"active","publicationStatus":"partial","evidenceStatus":"dated public-source review; some analysis and secondary reports","reviewDue":"2026-12-02","related":["qp-county-disclosure-2026","qp-county-pension-2026","qp-county-fiscal-review-2026"],"build":"Versioned salary schedule and payroll comparison data; compensation ratio scenario; no employee-level personal profiling.","privacy":"No commenter names or screenshots reproduced","validation":"Public-source arithmetic and source attribution; no certified audit"}},{"id":"qp-county-audit-cost-2026","title":"What audit is Pueblo County paying for — and why is it taking so long?","route":"county-audit-cost-and-delay.html","checked":"2026-11-18","reviewBy":"2026-12-02","questions":["Why is Pueblo County's audit taking so long?","What is Pueblo County paying Eide Bailly?","Can AI speed up the county audit?"],"keywords":["audit cost","eide bailly","county audit delay","accounting consultant","continuous audit"],"summary":"County reports accounting-close support September 29 and independent fieldwork starting the week of October 26. A separate October 1 financial management engagement has a reported $170,950 ceiling; that is not the independent audit fee. [S1,S2]","chapters":[{"heading":"Three distinct consulting scopes","text":"County reports August 18 budget preparation support, September 29 closing/reconciliation and statement compilation support, and October 1 executive/controller support. None is automatically the independent financial statement audit. [S1]","kind":"options"},{"heading":"What is known about price","text":"Secondary reporting describes 13 weeks at $7,900 for approximately 24 hours/week and 13 weeks at $5,250 for approximately 16 hours/week. Calculated total: $102,700 + $68,250 = $170,950 over 520 approximate hours, or $328.75 per nominal hour. This is a schedule/ceiling, not an invoice or actual cost. [S2,S3]","kind":"context"},{"heading":"Timeline and bottleneck","text":"The normal audit delivery deadline was June 30; July 31 is the normal state filing or extension-request deadline. A controller joined August 24; closing support was authorized September 29; drafts reached auditors in late October. The county's stated fieldwork start implies preparation was delayed, not that the independent auditor had been working on fieldwork all year. [S1,S4]","kind":"context"},{"heading":"October governance event","text":"October 2 reporting describes the October 1 CFO demotion, temporary finance supervision and a commissioner saying monthly reports remained unavailable. Attribute this to reporting, not an independent finding of individual culpability. [S2]","kind":"context"},{"heading":"Audit versus compilation versus forensic review","text":"A compilation helps assemble data; a financial statement audit tests evidence and expresses an opinion; a forensic investigation examines defined allegations or transactions. A grant Single Audit addresses applicable federal awards and compliance. These scopes and fees must stay separate.","kind":"context"},{"heading":"What public evidence can do now","text":"A desk review can reconstruct authorizations, compare years, recalculate totals, flag late reporting and inspect debt disclosures. It cannot confirm bank balances, completeness of liabilities or authorized signatures without underlying evidence. No CORA request is needed to publish the desk-review findings.","kind":"context"},{"heading":"Why the system should change","text":"A public-facing status labelled achieved can reflect an intermediate milestone. Track books closed, bank reconciled, schedules compiled, draft delivered, fieldwork started, opinion signed, state accepted and public report published separately. [S1]","kind":"context"},{"heading":"Continuous assurance pilot","text":"Use export-only financial data, deterministic bank-to-ledger matching and duplicate invoice checks, period-close calendar, exception register and monthly approval. AI can extract or explain, but cannot approve payments or certify financial statements.","kind":"context"},{"heading":"Audit independence and controls","text":"Separate preparation from independent assurance. Require named accountable owners, auditor independence review, sampling and materiality policy, evidence retention, read-only access and documented exception disposition. Retain a manual fallback.","kind":"context"},{"heading":"Public cost packet","text":"For each SOW store resolution, vendor, scope, ceiling, amendments, invoices, paid amounts, deliverables, dates, dependencies and acceptance sign-off. No cost summation until overlap and contract identity are reconciled.","kind":"context"},{"heading":"Workforce and children","text":"Repeated reconciliation consumes staff capacity while budget cuts threaten service continuity. Test whether staff training and process redesign reduce errors without shifting burdens to families or eliminating human review.","kind":"context"},{"heading":"EE / LL / T2Y","text":"Measure time to close, age of unmatched transactions, corrections per period, nonduplicated consultant costs and staff hours saved after review. Maintain lessons across administrations. Compare the actual monthly close with the target, not the stated intent.","kind":"options"},{"heading":"RX and leap","text":"Pilot one completed month in parallel using approved local exports. Test totals to source, role segregation, restore/rollback and exception detection. Expand only after finance leaders and independent reviewers accept the results.","kind":"options"},{"heading":"Event horizons","text":"In December 2026 check completion and actual procurement status. In 2027 track monthly close cadence and the next audit; in 2029 compare recurrence of findings, costs and staff workload. The five-year gate is sustained controls, not merely software purchased.","kind":"options"}],"unknowns":["2025 independent audit firm, fee, final opinion and filing not verified.","August and September SOW prices, amendments and payments not reconciled.","Full internal ledgers and reconciliation workpapers are not publicly established."],"sources":[{"id":"S1","title":"County priorities dashboard — November 2026","url":"https://county.pueblo.org/board-county-commissioners-office/what-we-are-working"},{"id":"S2","title":"Pueblo Chieftain reporting, October 2, syndicated by AOL","url":"https://www.aol.com/articles/pueblo-county-removes-cfo-hires-090821000.html"},{"id":"S3","title":"Contract extraction — October 1 agenda, secondary source","url":"https://civiciq.com/public-contract/pueblo-area-cog-mpo-and-tpr-co-eide-bailly-advisory-llc-consulting-2026-10-01"},{"id":"S4","title":"State Auditor filing calendar","url":"https://content.leg.colorado.gov/agencies/office-state-auditor/calendars-and-due-dates"},{"id":"S5","title":"2024 ACFR — independent audit report","url":"https://county.pueblo.org/sites/default/files/2025-11/Pueblo%20County%20Annual%20Comprehensive%20Financial%20Report%202024.pdf"},{"id":"S6","title":"County proposed 2027 budget","url":"https://county.pueblo.org/sites/default/files/2026-10/2027%20Proposed%20Budget%20SB.pdf"}],"packet":{"schemaVersion":"1.0","lifecycle":"active","publicationStatus":"partial","evidenceStatus":"dated public-source review; some analysis and secondary reports","reviewDue":"2026-12-02","related":["qp-county-disclosure-2026","qp-county-fiscal-review-2026","qp-regional-packets-2026"],"build":"Milestone tracker, contract cost registry, read-only continuous-assurance pilot design. No live ledger access.","privacy":"No commenter names or screenshots reproduced","validation":"Public-source arithmetic and source attribution; no certified audit"}},{"id":"qp-county-fiscal-review-2026","title":"What Pueblo County’s published numbers already reveal about the budget crisis","route":"county-public-financial-review.html","checked":"2026-11-18","reviewBy":"2026-12-02","questions":["What do Pueblo County's public finances reveal?","Why does the 2027 county budget rely on borrowing and asset sales?","How much is the proposed sheriff reduction?"],"keywords":["county deficit","county financial review","fund balance","debt service","2027 cuts","asset sale"],"summary":"The 2024 audited General Fund balance was $41.95M, including only $4.85M unassigned. The 2027 proposal projects a narrow $1.26M annual surplus and its opening-balance assumptions include $22M of anticipated financing and asset sales. [S1,S2]","chapters":[{"heading":"Historical audited position","text":"At December 31, 2024: General Fund total $41,950,453; nonspendable $2,038,078; restricted $18,166,573; committed $10,000,000; assigned $6,893,451; unassigned $4,852,351. The five sum exactly. Unassigned is 11.57% of total, not a cash balance. [S1 p17]","kind":"context"},{"heading":"Transfers mask the underlying sensitivity","text":"2024 General Fund fell $2,159,812; management discussion reports a $4.8M transfer from excess marijuana tax funds. Holding all else equal, without that transfer the decrease would be approximately $6.96M. This is a counterfactual, not an allegation about legality. [S1]","kind":"context"},{"heading":"Budget basis is different","text":"December 2024 GAAP fund balance and October 2026 budgetary projections are not directly subtractable. Before comparing, reconcile transfers, investment valuation and reporting basis; do not label the difference cash lost. [S1 pp17,104; S2 p9]","kind":"context"},{"heading":"2027 all-funds proposal","text":"The October presentation compares $255.83M 2026 spending with $217.28M 2027 preliminary spending, a $38.55M difference; the General Fund shown in that table is before recommended reductions. This is not realized savings. [S2 p2]","kind":"context"},{"heading":"2027 General Fund math","text":"Proposed revenues plus transfers $122.67M and expenses after cuts $121.40M; difference at displayed precision $1.27M versus reported $1.26M, plausibly rounding. The outlook displays starting expenses $131.21M, reductions $9.81M and spending $121.39M. [S2 p8; S3]","kind":"context"},{"heading":"Personnel reduction screen","text":"The outlook shows 15%, a $66.96M eligible personnel base and $9.81M reduction. Straight multiplication gives $10.044M, a $234,000 difference. The slide says grant-backed/exempt personnel are excluded and elected offices can meet targets in other categories. Reconcile basis and rounding; not evidence of lost cash. [S3 reduction slide]","kind":"options"},{"heading":"Distribution","text":"Sheriff $46.33M preliminary, $4.89M cut, $41.44M remaining (10.55%; 49.85% of $9.81M total). DA $6.42M to $5.58M, $0.84M reduction (13.08%); facilities $0.68M, clerk $0.60M, planning $0.49M, IT $0.48M. Dollar targets are not layoff counts. [S2 p6]","kind":"context"},{"heading":"Financing dependency","text":"Slide 9 explains that the General Fund opening estimate for 2027 incorporates unaudited 2025 and 2026 projections, including $7M anticipated asset sale and $15M anticipated COP. Projected end-2026 $0.90M; if neither arrived and all else held constant, $0.90M − $22M = −$21.10M. Not a forecast or proof of issuance. [S2 p9]","kind":"context"},{"heading":"Other funds","text":"2026 to 2027 projected endings: Road and Bridge −$5.48M to −$5.10M; Human Services $0 to −$0.50M; E911 $4.23M to $4.91M; Excess Marijuana $0.54M to $0.94M; Desert Hawk Golf $1.29M to $1.56M. Restricted resources cannot be assumed transferable. [S2 p9]","kind":"context"},{"heading":"Debt and recurring costs","text":"Proposed General Fund debt service $21.35M versus $20.22M 2026; capital $1.11M versus $20.13M. Review COP series, collateral, trustee dates and payments through original financing disclosures; a capital decline is not an equivalent recurring cost saving. [S2 p5; S5]","kind":"context"},{"heading":"Shock test","text":"Use reported annual surplus $1.26M minus revenue loss and unmet savings. At 1% revenue loss ($1.2267M), remaining margin is $33,300; at 2%, deficit $1.1934M. If 90% of $9.81M savings materializes with no other change, surplus $279,000. These are static scenarios, not forecasts; do not double count missing proceeds in annual and opening-balance calculations.","kind":"context"},{"heading":"Crossover and child impact","text":"Assess jail obligations, pension funding, wildfire recovery, road maintenance, drought, wastewater and service disruptions together. Reduced household income and access to human services are possible knock-on effects; require outcome data before assigning causal effects.","kind":"context"},{"heading":"Q processing","text":"Retain native dollar amounts, fund, fiscal period, accounting basis, proposal/adoption/actual stage and cited slide or page. Recalculate with integer cents; flag inconsistent rows; keep raw values and derived values separate. Match counterparties for interfund transfers.","kind":"options"},{"heading":"EE / RX / event horizons","text":"Public-source first; measure recurring revenue against recurring expenditure before financing. In 2027 monitor actual receipts, savings, debt and fund ending balance. In 2029/2031 test reserve recovery and maintenance backlog. Compare alternatives without assuming that all cuts or asset sales are avoidable.","kind":"options"}],"unknowns":["2025 audited actuals and 2026 finalized accounts missing from checked archive.","Exact eligible-payroll reduction bridge not published in reviewed slides.","Actual financing proceeds, asset-sale completion and final adopted 2027 budget not verified."],"sources":[{"id":"S1","title":"2024 ACFR — printed pp. 17, 21, 104 and notes","url":"https://county.pueblo.org/sites/default/files/2025-11/Pueblo%20County%20Annual%20Comprehensive%20Financial%20Report%202024.pdf"},{"id":"S2","title":"2027 proposed budget — slides 2–9","url":"https://county.pueblo.org/sites/default/files/2026-10/2027%20Proposed%20Budget%20SB.pdf"},{"id":"S3","title":"2027 financial outlook — reduction plan and surplus","url":"https://county.pueblo.org/sites/default/files/2026-10/2027%20Financial%20Update%20Final.pdf"},{"id":"S4","title":"2027 budget portal","url":"https://county.pueblo.org/budget-and-finance-department/2027-budget"},{"id":"S5","title":"Public municipal securities disclosures","url":"https://emma.msrb.org/"}],"packet":{"schemaVersion":"1.0","lifecycle":"active","publicationStatus":"partial","evidenceStatus":"dated public-source review; some analysis and secondary reports","reviewDue":"2026-12-02","related":["qp-county-audit-cost-2026","qp-county-pension-2026","qp-regional-fragmentation-2026"],"build":"Financial calculation ledger, scenario inputs, reconciliation checks and source-linked fund timeline.","privacy":"No commenter names or screenshots reproduced","validation":"Public-source arithmetic and source attribution; no certified audit"}},{"id":"qp-county-pension-2026","title":"Pueblo County pension funding, workforce cuts and future obligations","route":"county-pension-and-workforce.html","checked":"2026-11-18","reviewBy":"2026-12-02","questions":["How underfunded is Pueblo County's pension?","What could workforce cuts mean for pensions?","Are county commissioners in PERA?"],"keywords":["county pension","retirement","pension funding","deputy layoffs","workforce sustainability"],"summary":"The 2024 ACFR reports $145.10M net liability for the county officers and employees plan, $423,031 PERA net liability and a $4.215M actuarial contribution shortfall for the county plan. These are long-term obligations, not current General Fund bills. [S1]","chapters":[{"heading":"Pension balance sheet","text":"At December 31, 2024, total pension liability $314,240,583 minus fiduciary net position $169,141,289 = net liability $145,099,294; assets are 53.83% of liability. 2023 net liability $133,241,186; increase $11,858,108. [S1 p78]","kind":"options"},{"heading":"Separate PERA participation","text":"The county reports PERA net liability $423,031 and combined reported net pension liability $145,522,325. This does not establish which individual elected officials are enrolled in either plan. [S1 p89]","kind":"context"},{"heading":"2024 cash movement","text":"Employer contributions $8,188,507; employee contributions $6,004,905; benefits paid $19,875,889; investment income $10,823,331. Benefits are not an operating deficit and investment income is not guaranteed. [S1 p78]","kind":"context"},{"heading":"Contribution history","text":"Actuarially determined versus actual employer contributions (millions, rounded): 2015 6.34/3.83; 2016 6.88/4.06; 2017 7.15/4.17; 2018 7.32/4.31; 2019 8.03/4.72; 2020 9.55/5.13; 2021 9.56/6.14; 2022 10.90/6.88; 2023 11.49/7.82; 2024 12.40/8.19. Shortfalls occur in all ten reported years, across administrations. [S1 p111]","kind":"context"},{"heading":"Exact current historical shortfall","text":"$12,403,537 − $8,188,507 = $4,215,030 in 2024. The schedule reports a contribution of 11.22% of covered payroll; that ratio is not necessarily the statutory or policy contribution rate. [S1 p111]","kind":"context"},{"heading":"Discount-rate sensitivity","text":"The actuarial disclosure gives $181,528,875 net liability at 6%, $145,099,294 at 7%, and $114,433,124 at 8%. These are valuation scenarios, not an immediate demand for cash or proof of insolvency. [S1 p78]","kind":"context"},{"heading":"Layoff crossover","text":"Covered payroll $72,951,948 in 2024. A reduction in payroll can reduce payroll-linked contributions, while accrued obligations do not disappear. Retirement timing, replacement hiring, contributions and asset returns require qualified actuarial modeling. [S1 p111]","kind":"context"},{"heading":"What workers and retirees need","text":"Clear benefit rules, accurate contributions, accessible aggregate funding data and independent advice. Q should not imply a pension reduction or benefit default or give personal retirement advice.","kind":"options"},{"heading":"Community signal","text":"Comments express concern about employee safety and fairness and claim commissioners use a different pension scheme. The aggregate ACFR cannot establish those individual enrollments. Keep the claim unresolved instead of amplifying it.","kind":"context"},{"heading":"Child impact and economic resilience","text":"Possible pathways include lost income, family housing instability and changes to service capacity. Retiree spending and the future tax/service tradeoff are regional concerns; not quantified outcomes.","kind":"context"},{"heading":"Q processing and EE","text":"Store actuarial measurement date, valuation method, discount rate, total liability, fiduciary assets, plan, contribution target and contributions. Do not conflate pension expense, contribution, debt principal or annual budget deficit. Reuse historic data once with auditable calculations.","kind":"options"},{"heading":"RX and event horizons","text":"Compare next valuation and ACFR, detect recurring deficiency, review employer-policy changes, model payroll and returns with an actuary. Evaluate year 3 and year 5 funding paths; no cost savings or changes to benefits assumed.","kind":"options"}],"unknowns":["2025 and 2026 liabilities and actuarial forecasts not verified.","Individual retirement enrollment and current contribution policy not reconciled.","Effect of proposed cuts on covered payroll and actuarial outcomes not calculated."],"sources":[{"id":"S1","title":"2024 county ACFR — printed pp. 78, 89, 110–111","url":"https://county.pueblo.org/sites/default/files/2025-11/Pueblo%20County%20Annual%20Comprehensive%20Financial%20Report%202024.pdf"},{"id":"S2","title":"County 2027 budget presentation","url":"https://county.pueblo.org/sites/default/files/2026-10/2027%20Proposed%20Budget%20SB.pdf"},{"id":"S3","title":"County annual report archive","url":"https://county.pueblo.org/budget-and-finance-department/annual-comprehensive-financial-report-acfr"}],"packet":{"schemaVersion":"1.0","lifecycle":"active","publicationStatus":"partial","evidenceStatus":"dated public-source review; some analysis and secondary reports","reviewDue":"2026-12-02","related":["qp-county-compensation-2026","qp-county-fiscal-review-2026","qp-regional-fragmentation-2026"],"build":"Pension historical series and sensitivity specifications; workforce linkage at aggregate level only.","privacy":"No commenter names or screenshots reproduced","validation":"Public-source arithmetic and source attribution; no certified audit"}},{"id":"qp-regional-fragmentation-2026","title":"One Pueblo region, many disconnected reporting systems","route":"regional-fragmentation.html","checked":"2026-11-18","reviewBy":"2026-12-02","questions":["Why is Pueblo's regional reporting fractured?","How can Pueblo connect its government entities?","Why does Q Pueblo need to exist?"],"keywords":["regional fragmentation","pacog","regional reporting","jurisdictions","shared services"],"summary":"Public budgets and financial disclosures are maintained by separate institutions. PACOG already provides a regional coordination structure; Q proposes federated public information, not consolidated government. [S1–S5]","chapters":[{"heading":"Scope","text":"One regional economy intersects city and county boundaries, metro and special districts, schools, water, sanitation, libraries, emergency response, nonprofits, businesses and state/federal programs. These authorities retain different statutory mandates and records.","kind":"context"},{"heading":"Existing public reporting","text":"County, city, Pueblo West, Pueblo Water and schools have distinct sources. State filings offer a separate oversight channel. Differences in fiscal years and accounting bases prevent direct comparisons without reconciliation. [S2–S8]","kind":"context"},{"heading":"An existing coordinating body","text":"PACOG lists regional member government organizations and provides a forum for coordination. Q proposes exploring its convening role for compatibility; it has not been granted additional authority or adopted this design. [S1]","kind":"context"},{"heading":"Why the fragmentation costs matter","text":"Residents search multiple portals; entities may buy overlapping data, maps or technology; cross-jurisdictional dependencies are difficult to identify. These are hypotheses requiring time-and-cost baselines, not audited dollar losses.","kind":"context"},{"heading":"Follow the money","text":"A federal grant passed to the state, county and a local service provider can be recorded more than once. Match transfer amount, date, fund, counterparty and recognition basis. Sum comparable expenditures minus only matched duplicate internal flows; preserve unresolved matches.","kind":"context"},{"heading":"Illustrative regional case","text":"When county road maintenance is deferred, municipal and school transport patterns may change; emergency access and local business costs may be affected. Track service boundaries and jointly affected assets without asserting effects are already measured.","kind":"context"},{"heading":"Water and industry","text":"Link water rights, allocations, drought, wastewater, projects, industrial demand and utility capacity. Distinguish legal rights, physical water, seasonal availability and contracted use; avoid drawing conclusions from unrelated service territories.","kind":"context"},{"heading":"Fire and emergency","text":"Use verified event dates, recovery milestones, household assistance, grant and asset packets. Link each cost to the responsible entity and do not count promised assistance as paid. Year 3/5 recovery monitoring belongs alongside immediate response.","kind":"context"},{"heading":"Education and household impact","text":"Schools use different fiscal calendars. Child effects of transport, food availability, household income and service changes should be modeled in aggregate, without profiling children.","kind":"context"},{"heading":"Digital twin and shadow","text":"Twin: source-backed public facts about institutions, assets, responsibilities and connections. Shadow: historical versions, observed public concerns and scenarios; distinguish source-backed states from hypothetical outcomes. Neither controls physical infrastructure.","kind":"context"},{"heading":"Public signals","text":"Community comments are retained as dated thematic observations, not population sentiment or verified wrongdoing. Link them to claims and relevant sources; avoid publishing unnecessary identifiers. Preserve contradictory viewpoints.","kind":"context"},{"heading":"EE / T2Y / LL","text":"Measure duplicated research time and data acquisition; shared definitions and stable identifiers can reduce rework. Maintain time validity and versions, preserve dissent and recover existing Q evidence before new extraction.","kind":"options"},{"heading":"RX and leap","text":"Pilot common exports with willing partners and existing public archives. Use a read-only regional source registry and compatibility adapter rather than a centralized replacement. Human authority, local autonomy, legal retention and privacy remain intact.","kind":"options"},{"heading":"Horizon and success","text":"2027 inventory and pilots; 2029 reconciled financial flows and GIS relationships; 2031 independent resilience evaluation. Success means fewer unresolved matches, reliable publication and proven reduction in rework — not number of entities forced onto one platform.","kind":"options"}],"unknowns":["No complete current entity and service-boundary census.","No measured region-wide fragmentation cost.","Institutional adoption, agreements and legal scope not established."],"sources":[{"id":"S1","title":"PACOG — participating organizations and structure","url":"https://www.pacog.net/whoispacog"},{"id":"S2","title":"County annual financial report archive","url":"https://county.pueblo.org/budget-and-finance-department/annual-comprehensive-financial-report-acfr"},{"id":"S3","title":"City Finance","url":"https://www.pueblo.us/92/Finance"},{"id":"S4","title":"Pueblo West budget and financial reports","url":"https://www.pueblowestmetro.us/548/Budget-and-Annual-Financial-Reports"},{"id":"S5","title":"Pueblo Water financials","url":"https://pueblowater.org/our-board/financials/"},{"id":"S6","title":"State Auditor public local audit repository","url":"https://apps.leg.co.gov/osa/lg"},{"id":"S7","title":"District 60 financial transparency","url":"https://www.pueblod60.org/departments/business-services/financial-transparency"},{"id":"S8","title":"District 70 financial transparency","url":"https://www.district70.org/district-information/district-departments/business-services/financial-transparency"}],"packet":{"schemaVersion":"1.0","lifecycle":"active","publicationStatus":"partial","evidenceStatus":"dated public-source review; some analysis and secondary reports","reviewDue":"2026-12-02","related":["qp-regional-packets-2026","qp-regional-leap-2026","qp-county-fiscal-review-2026"],"build":"Federated regional source inventory and entity relationship schema; no new authority or institutional consolidation.","privacy":"No commenter names or screenshots reproduced","validation":"Public-source arithmetic and source attribution; no certified audit"}},{"id":"qp-regional-packets-2026","title":"AI-compatible public records: the Q living packet transition","route":"regional-ai-compatible-packets.html","checked":"2026-11-18","reviewBy":"2026-12-02","questions":["What does AI-compatible government reporting mean?","How should Pueblo build public knowledge packets?","How can government avoid repeated audit reconstruction?"],"keywords":["AI compatible","packet standard","machine readable","continuous assurance","AI governance","interoperability"],"summary":"Q proposes source-linked, versioned, human-readable and machine-readable packets for financial records, projects, decisions and AI tools. Data remains owned by responsible institutions; public exports do not grant access to confidential records.","chapters":[{"heading":"Why a packet rather than another PDF?","text":"A published PDF preserves a document, but searchable structured records can also expose amounts, dates, relationships and provenance without repeated extraction. Keep the authentic original and generate accessible HTML, CSV/JSON and a stable record identifier.","kind":"context"},{"heading":"Native creation","text":"Create a decision packet when a board authorizes a contract, not after a dispute. Include authority, signoff, amount, fund, vendor, milestone, effective dates, dependencies and public classification; append payment, amendment and outcome events.","kind":"context"},{"heading":"Minimum data","text":"packet_id, entity_id, jurisdiction, schema_version, record_type, reporting_period, effective_date, source URI, observed_at, source hash if captured, claim status, review_due, fields with units and evidence IDs, revision history, related packets, owner role and access classification. Unknown is null, never zero.","kind":"context"},{"heading":"Human-readable and machine-readable","text":"A resident reads plain language with original citations; an authorized tool reads validated JSON using a published data dictionary. Public export excludes bank details, protected employee records, privilege, security-sensitive configuration and personal information.","kind":"context"},{"heading":"Financial validation","text":"Record authorization, commitment, invoice, payment, amendment, accounting basis, fund restriction and counterparty independently. Reconcile totals and reject incompatible fiscal periods. Run deterministic arithmetic before AI summarization.","kind":"context"},{"heading":"Audit packet example","text":"2025 county audit record: fiscal close 2025-12-31; normal audit date 2026-06-30; county-reported fieldwork week 2026-10-26; independent fee, final opinion and state filing unknown. Keep separate consulting ceiling $170,950 only in its own contract record, not as audit fee. [S4 and linked investigation]","kind":"context"},{"heading":"Versioning and TTL","text":"The packet remains open as evidence evolves. Review dates trigger freshness checks; expired observations remain historical with explicit dates. Corrections append reasons and source lineage. An unavailable source is not deleted or replaced silently.","kind":"context"},{"heading":"AI uses and boundaries","text":"Offer retrieval, relevant comparison, anomaly flags and plain-language explanations. Treat retrieved text as untrusted content, cite source-level facts and abstain from unsupported claims. Do not allow AI to authorize expenditure, decide eligibility or control critical infrastructure.","kind":"context"},{"heading":"Governance register","text":"Record AI tool purpose, owner, policy authority, affected population, data classes, model/provider version, test results, risk controls, human appeals, accessibility, security, procurement and exit plan. UK's transparency register illustrates public standardized records. [S2]","kind":"context"},{"heading":"Interoperability precedents","text":"GAO's May 2026 report identifies potential efficiency of standardized regulatory reporting; it is not a claim all agencies have achieved it. Estonia's exchange infrastructure illustrates independent institutions sharing authorized data. [S1,S3]","kind":"context"},{"heading":"Procurement acceptance","text":"Require documented export/data dictionary, stable IDs, legal ownership, access control, portability, migration cost, independent checks, manual fallback and deletion/retention rules. Test actual exports before acceptance; do not require one vendor or AI model.","kind":"context"},{"heading":"Child and rights safeguards","text":"Never attach identifiable child data to public packets. Test accessibility for residents without smartphones or broadband; provide static reading, printable formats and non-AI referral paths. Keep humans accountable for high-impact decisions.","kind":"context"},{"heading":"EE and T2Y","text":"Measure time per accepted record, duplicate extraction avoided, error correction, data freshness and energy/compute costs. Prefer structured deterministic processing and cached sources over repeated model calls. Measure answer fidelity and preserve years of context.","kind":"options"},{"heading":"RX, failure modes and leap","text":"Reject malformed inputs, mark contested claims, retain previous known-good release, support revocation of compromised access and rollback. Start read-only with public finance; scale only after reproducible checks and owner approval.","kind":"options"}],"unknowns":["No government adoption or live private-system integration.","No measured local efficiency gain or procurement quotes.","A production regional schema and access policy require stakeholder and legal validation."],"sources":[{"id":"S1","title":"GAO May 2026 — Financial Data Transparency Act reporting reform","url":"https://www.gao.gov/products/gao-26-108420"},{"id":"S2","title":"UK algorithmic transparency recording standard hub","url":"https://www.gov.uk/government/collections/algorithmic-transparency-recording-standard-hub"},{"id":"S3","title":"Estonia RIA X-tee data exchange","url":"https://www.ria.ee/en/state-information-system/data-exchange-platforms/data-exchange-layer-x-tee"},{"id":"S4","title":"County documented accounting close and controls","url":"https://county.pueblo.org/board-county-commissioners-office/what-we-are-working"}],"packet":{"schemaVersion":"1.0","lifecycle":"active","publicationStatus":"partial","evidenceStatus":"dated public-source review; some analysis and secondary reports","reviewDue":"2026-12-02","related":["qp-regional-fragmentation-2026","qp-regional-leap-2026","qp-county-audit-cost-2026"],"build":"Static machine-readable research packet export, source-linked reading, procurement compatibility checklist and architecture proposal.","privacy":"No commenter names or screenshots reproduced","validation":"Public-source arithmetic and source attribution; no certified audit"}},{"id":"qp-regional-leap-2026","title":"Pueblo’s transition and leap plan: real examples, costs and implementation","route":"regional-transition-and-leap.html","checked":"2026-11-18","reviewBy":"2026-12-02","questions":["How can Pueblo leap into the AI era?","What real government transitions can Pueblo learn from?","What does Q Pueblo propose for implementation?"],"keywords":["transition planning","leap planning","modernization","case studies","regional AI readiness","implementation"],"summary":"Real transitions in Estonia, the UK, procurement reform and Colorado regional data sharing provide reusable patterns. Q proposes staged, measured, reversible pilots — not a claim of proven local savings or authorized deployment.","chapters":[{"heading":"Estonia — interoperability","text":"X-tee enables authorized exchange across independent information systems. Reuse the architecture principle of compatible interfaces, authentication and traceability, not Estonia's laws or identity infrastructure wholesale. [S1]","kind":"context"},{"heading":"UK — coherent public access","text":"The digital strategy illustrates migrating disparate public publishing and services toward coherent access. Pueblo can offer one evidence navigation layer while preserving institutions' official sites and authority. [S2]","kind":"context"},{"heading":"Colorado — regional acquisition","text":"DRCOG coordinates regional data acquisition including imagery. Pueblo should inventory existing datasets and licensing before recommending new contracts or hardware. [S3]","kind":"context"},{"heading":"Ukraine — civic prototype to procurement reform","text":"The ProZorro case shows a civic-led pilot evolving into institutional procurement reform. Its reported results are context-specific; local legal and procurement adaptation plus independent measurement are needed. [S4]","kind":"context"},{"heading":"Federal reporting — data first","text":"GAO describes the potential to reduce repetitive filings through standards but also a need for initial government-wide foundations. Common syntax alone cannot reconcile definitions or poor data. [S5]","kind":"context"},{"heading":"UK governance — public records for AI","text":"ATRS supplies standardized disclosures and guidance for specified public-sector organizations. Q can adapt the pattern into a local tool registry with human appeal and assessment; it is not Colorado law. [S6]","kind":"context"},{"heading":"Local anchor","text":"PACOG already coordinates across regional jurisdictions. A voluntary interoperability discussion could build on current regional planning, not create another government agency. No participation is assumed. [S7]","kind":"context"},{"heading":"Six practical demonstrations","text":"Finance: document and simulate audit delays. Wildfire: connect recovery funding and household resources. Water: connect drought, wastewater and capacity. Jail: follow construction, debt and operations. Industry: track jobs, incentives and resource demands. Education: map skills pathways. Each begins with public evidence and a no-change baseline.","kind":"context"},{"heading":"Three delivery lanes","text":"A: Q independently publishes public-source packets. B: willing institutions provide structured exports through agreements. C: authorized internal systems implement tested controls. A can work while B/C remain proposals; do not connect sensitive systems in the public prototype.","kind":"options"},{"heading":"Illustrative economics","text":"Eight entities × 20 duplicated hours/month × 12 × $50 loaded cost = $96,000/year of modeled labor. At 40% reuse, $38,400 time value; less $25,000 annual operation = $13,400 modeled benefit; $60,000 setup / $13,400 ≈ 4.48 years simple payback. These are assumptions, not measured Pueblo costs or cash savings.","kind":"context"},{"heading":"First 30–90 days","text":"Inventory systems, sources, reporting periods, permissions, existing contracts, staff skills and baseline hours. Pilot one export and one public answer with accessibility tests, source reconciliation, security review, manual fallback and an explicit stop gate.","kind":"context"},{"heading":"2027–2028 transition","text":"Publish source registry, public financial packet demonstrations, regional comparison and correction channel. Test voluntary adapters with one or two willing institutions. Evaluation: traceable claims, consistent data, time and cost per accepted output versus manual baseline.","kind":"context"},{"heading":"2029 and 2031 leap","text":"Year 3: reconcile cross-entity flows and map infrastructure dependencies. Year 5: independently evaluate continuous assurance, maintenance and disaster scenarios. Only advance if data quality, privacy, cost and service continuity pass review.","kind":"options"},{"heading":"2036 and longer","text":"Maintain versioned data definitions, open exports, tested restore, succession, funding and exit plans. Avoid locking decades of public information into proprietary or obsolete systems.","kind":"context"},{"heading":"Failure modes and correction","text":"ERP migrations can fail under rushed adoption, poor source quality or inadequate training. Do not migrate critical systems during a budget crisis without parallel validation. Watch vendor lock-in, sensitive-data leakage, unsupported AI claims, digital exclusion and duplicated procurement.","kind":"context"},{"heading":"Child and workforce impact","text":"Offer digital literacy and accessible non-AI paths. Assess retraining, staffing impacts, emergency service continuity and intergenerational infrastructure costs before expansion. No automated employment or public-benefit decision-making.","kind":"context"},{"heading":"LL / EE / T2Y / RX","text":"Capture each pilot’s baseline, methods, failures, costs and corrections; reuse validated components. Compare output accuracy and rework, energy and staff review. Pause or rollback on integrity failure; preserve human judgment.","kind":"options"},{"heading":"Qified conclusion","text":"Independent public intelligence, compatible information, region-wide understanding and human authority can coexist. The near-term leap is reliable, explainable knowledge — not an expensive AI purchase or centralization.","kind":"context"}],"unknowns":["Actual regional staffing, software and duplicated work baselines not yet measured.","Pilot budgets, funding and participating institutions not authorized.","No production digital twin or autonomous AI service implied."],"sources":[{"id":"S1","title":"Estonia RIA — X-tee exchange","url":"https://www.ria.ee/en/state-information-system/data-exchange-platforms/data-exchange-layer-x-tee"},{"id":"S2","title":"UK government digital strategy","url":"https://www.gov.uk/government/publications/government-digital-strategy/government-digital-strategy"},{"id":"S3","title":"DRCOG regional data acquisition","url":"https://drcog.org/data-maps-modeling/data-acquisition-projects"},{"id":"S4","title":"Open Contracting Partnership — ProZorro case study","url":"https://www.open-contracting.org/2016/07/28/prozorro-volunteer-project-led-nation-wide-procurement-reform-ukraine/"},{"id":"S5","title":"GAO regulatory reporting transition May 2026","url":"https://www.gao.gov/products/gao-26-108420"},{"id":"S6","title":"UK algorithmic transparency standard","url":"https://www.gov.uk/government/collections/algorithmic-transparency-recording-standard-hub"},{"id":"S7","title":"PACOG coordination","url":"https://www.pacog.net/whoispacog"}],"packet":{"schemaVersion":"1.0","lifecycle":"active","publicationStatus":"partial","evidenceStatus":"dated public-source review; some analysis and secondary reports","reviewDue":"2026-12-02","related":["qp-regional-fragmentation-2026","qp-regional-packets-2026","qp-county-fiscal-review-2026"],"build":"Case study library, staged implementation gates, duplication-cost scenario and six demonstration briefs.","privacy":"No commenter names or screenshots reproduced","validation":"Public-source arithmetic and source attribution; no certified audit"}}];
 regionalStories.push({"id":"qp-county-public-safety-child-2026","title":"What could Pueblo County’s proposed budget cuts mean for deputies, detention and school safety?","route":"county-public-safety-school-resource-officers.html","checked":"2026-11-18","reviewBy":"2026-11-24","questions":["Are Pueblo County school resource officers being cut?","How could Pueblo County budget cuts affect public safety?","What does the $4.89 million Sheriff budget reduction mean?"],"keywords":["school resource officer","school resource officers","SRO","deputy staffing","sheriff budget","school safety","detention staffing","child safety"],"summary":"The proposed Sheriff reduction is $4.89M, or 10.55% of its preliminary budget. Frontline testimony raises concern about patrol, detention and District 70 SRO continuity. Final staffing decisions and current program costs are not established. [S1,S3,S4,S7]","sources":[{"id":"S1","title":"County — October 15 proposed budget presentation, slide 6","url":"https://county.pueblo.org/sites/default/files/2026-10/2027%20Proposed%20Budget%20SB.pdf"},{"id":"S2","title":"County — 2027 budget portal and calendar","url":"https://county.pueblo.org/budget-and-finance-department/2027-budget"},{"id":"S3","title":"County — November financial progress and budget targets","url":"https://www.pueblocounty.gov/board-county-commissioners-office/what-we-are-working"},{"id":"S4","title":"Citizen Portal — November 3 meeting transcript summary; secondary source","url":"https://citizenportal.ai/source/11869934/board-of-county-commissioners-meeting"},{"id":"S5","title":"Zonewire — November 17 work session summary; secondary source","url":"https://www.zonewire.co/meetings/pueblo-county/11097"},{"id":"S6","title":"Sheriff — 2024 accountability report, Patrol, SRO and Judicial Intake sections","url":"https://www.pueblosheriff.com/Archive/ViewFile/Item/5493"},{"id":"S7","title":"District 70 — Student Services and SRO program","url":"https://www.district70.org/district-information/district-departments/student-services"},{"id":"S8","title":"C.R.S. 30-11-107(2) — budget authority, 2025 statutory reproduction","url":"https://law.justia.com/codes/colorado/title-30/county-powers-and-functions/general/article-11/part-1/section-30-11-107/"},{"id":"S9","title":"C.R.S. 30-10-511 — jail custody, 2025 statutory reproduction","url":"https://law.justia.com/codes/colorado/title-30/county-officers/article-10/part-5/section-30-10-511/"},{"id":"S10","title":"Colorado Supreme Court — Tihonovich v. Williams (1978)","url":"https://law.justia.com/cases/colorado/supreme-court/1978/27500.html"},{"id":"S11","title":"Colorado — mandated child abuse reporting guidance","url":"https://co4kids.org/child-abuse-prevention/mandatory-reporters/"},{"id":"S12","title":"Safe2Tell — anonymous student safety reporting","url":"https://safe2tell.org/"},{"id":"S13","title":"2023 quasi-experimental national SRO study","url":"https://onlinelibrary.wiley.com/doi/10.1002/pam.22498"},{"id":"S14","title":"2023 systematic review of school-based policing","url":"https://pubmed.ncbi.nlm.nih.gov/38024781/"},{"id":"S15","title":"Colorado Department of Education — multidisciplinary school violence prevention","url":"https://ed.cde.state.co.us/mtss/psv"},{"id":"S16","title":"County meeting agenda and records portal","url":"https://pueblococo.portal.civicclerk.com/"},{"id":"S17","title":"County — official planning calendar PDF","url":"https://county.pueblo.org/sites/default/files/2026-10/2027%20Budget%20Meeting%20Calendar.pdf"},{"id":"S18","title":"Pueblo Ledger — November 14 budget explanation; secondary source","url":"https://puebloledger.com/government-watch/pueblo-2027-budgets-city-county/"},{"id":"S19","title":"KRDO — January 31, 2026 furlough discussion and projected holiday savings","url":"https://krdo.com/news/top-stories/2026/01/31/pueblo-county-discusses-furloughing-workers-to-address-10-million-budget-shortfall/"},{"id":"S20","title":"KRDO — November 17, 2026 proposed municipal-offense jail agreement","url":"https://krdo.com/news/2026/11/17/pueblo-considers-jail-time-for-low-level-offenders-ordinance-to-be-voted-on-monday/"},{"id":"S21","title":"Pueblo Municipal Court — existing jurisdiction and penalty authority","url":"https://www.pueblo.us/99/Municipal-Court"}],"chapters":[{"kind":"context","heading":"A budget target and a frontline warning","text":"A supplied open letter, signed Eloysa Trujillo, raises concerns about service capacity and the continuity of trusted relationships between officers and children. Treat this as firsthand testimony, not verified conclusions about officials’ motives or the precise meeting record."},{"kind":"money","heading":"Follow the $4.89 million","text":"The official October budget presentation shows $46.33M before, $4.89M reduction and $41.44M after proposed reductions. The Sheriff's share is 49.85% of $9.81M planned General Fund reductions. Dollar targets are not layoffs. [S1,S3]"},{"kind":"people","heading":"Who decides?","text":"The board adopts the budget, the sheriff recommends and administers its operations, and District 70 governs its school environment and agreements. Colorado law preserves statutory responsibilities and budget discretion. [S7–S10]"},{"kind":"chronology","heading":"A documented record, not just a social post","text":"November 3 union and patrol testimony reportedly warned of shortages; November 17 work session reporting describes seeking legal advice. The 2024 Sheriff report records 33,232 patrol calls versus 36,378 in 2023 and reports an SRO program serving more than 20 schools. Current trends and proposed position changes need verification. [S4–S6]"},{"kind":"meaning","heading":"Children, deputies and detention residents","text":"Public safety means effective response, humane custody, trusted reporting, staff wellbeing and equitable student outcomes. Observe potential harm before changing services and avoid disclosing sensitive assignments or identifiable child records. National research on SRO effects is mixed, including discipline concerns. [S11–S15]"},{"kind":"options","heading":"Alternatives and net savings","text":"Review legally available recurring spending, actual vacancies, grant restrictions, district partnership and service redesign. Compare net avoidable costs with overtime, implementation and transition costs; protect statutory duties and continuity. The $4.89M target is not an established achievable alternative saving."},{"kind":"future","heading":"Decision gates","text":"Official schedule: December 4 adjustment deadline and December 10 public hearing, subject to change. Before adoption, publish aggregate service-impact scenarios, options, accounting basis and responsible roles; after adoption, track actual costs, service outcomes and corrections. [S17]"},{"kind":"chronology","heading":"November 18 media lead and earlier warning signs","text":"A supplied KRDO13 screenshot links to a November 18 report about a sheriff layoff warning (L1). The article could not be retrieved, so no layoff count or quotation is attributed to it. Independently, KRDO reported January 31 that the county was considering employee furloughs in response to a roughly $10M shortfall and anticipated $1.5M savings from unpaid holidays. The stated savings are not verified actuals. [S19]"},{"kind":"meaning","heading":"City jail policy and county staffing: a regional crossover","text":"KRDO reported November 17 that the City was pursuing a city–county agreement concerning custody and sentencing for specified municipal offenses; City Council consideration was scheduled November 23 and county approval would also be needed. The mayor said additional housing costs would fit the police budget; the agreement, rate, additional bed-days and actual impact remain unverified. Existing Municipal Court authority should not be confused with the proposed change. [S20,S21] Q proposes reconciling incremental bookings, bed-days, marginal medical and staffing costs, city reimbursements, due process, alternative sanctions and family effects before assuming the two policies are financially compatible."}],"unknowns":["Exact original date and full recording of the supplied testimony; no official finding on the author's allegations.","Current budgeted versus filled posts, verified vacancies, SRO agreement and approved staffing changes.","Current aggregate workload, response and service continuity metrics; no operational vulnerabilities published.","Local child protection outcomes and costed alternatives; no causal estimate or forecast.","Unable to retrieve full preliminary budget book due to file size; sheriff report text accessible but page screenshots unavailable.","November 18 KRDO article body, attributed layoff estimates and exact timing have not been retrieved; screenshot is a lead only.","Proposed municipal jail agreement text, reimbursement formula, forecast bed-days and final approvals not verified."],"coverage40":[{"n":1,"title":"Scope","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"The proposed 2027 county General Fund budget, patrol and detention service capacity, and District 70 school safety. County and city police budgets are different."},{"n":2,"title":"Frontline testimony","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"The supplied open letter, signed Eloysa Trujillo, describes the writer's experience as a deputy and school resource officer and expresses concern about cuts. It is retained as a testimonial signal; the original public post and exact meeting date were not independently verified. The full letter and child case details are not reproduced."},{"n":3,"title":"Proposed Sheriff budget","classification":"Dated source finding","sourceIds":["S1"],"answer":"The October presentation lists $46.33M preliminary, $4.89M reduction and $41.44M after reduction."},{"n":4,"title":"Reduction rate","classification":"Q analysis or practical guidance","sourceIds":["S1"],"answer":"4.89 / 46.33 × 100 = 10.55% of the preliminary Sheriff budget. The county's 15% target applies to eligible personnel costs, not all departmental spending."},{"n":5,"title":"Share of county reductions","classification":"Q analysis or practical guidance","sourceIds":["S1","S3"],"answer":"4.89 / 9.81 × 100 = 49.85%. This is a share of planned dollar reductions, not a share of workers losing jobs."},{"n":6,"title":"County's fiscal rationale","classification":"Dated source finding","sourceIds":["S3","S18"],"answer":"County describes a need to balance spending and revenue. Local reporting identifies reduced marijuana tax receipts, higher insurance, health and jail medical costs, and earlier capital obligations. A complete cause-by-cause reconciled ledger is not established."},{"n":7,"title":"Final budget status","classification":"Not established","sourceIds":[],"answer":"No final adopted 2027 budget, implementation roster or enacted SRO elimination was established in this review."},{"n":8,"title":"County discretion","classification":"Dated source finding","sourceIds":["S1","S3"],"answer":"The county states elected offices can meet dollar targets through various spending categories; not every reduction must be a layoff."},{"n":9,"title":"Board authority","classification":"Dated source finding","sourceIds":["S8"],"answer":"Section 30-11-107(2) assigns the board final annual budget adoption authority, with department and elected-office budget recommendations."},{"n":10,"title":"Sheriff duty","classification":"Dated source finding","sourceIds":["S9"],"answer":"Section 30-10-511 places county jail custody and supervision with the sheriff, subject to the legal exception stated in the statute."},{"n":11,"title":"Legal balancing","classification":"Dated source finding","sourceIds":["S10"],"answer":"Tihonovich v. Williams discusses county budget discretion in light of revenue, taxpayer capacity, other services and department needs. This is not a ruling on Pueblo's 2027 proposal."},{"n":12,"title":"November 3 testimony","classification":"Dated source finding","sourceIds":["S4"],"answer":"A secondary meeting summary attributes staffing and safety warnings to a patrol sergeant and union representative. Watch the original recording before treating the transcript as authoritative."},{"n":13,"title":"Vacancy claims","classification":"Dated source finding","sourceIds":["S4"],"answer":"The union representative reportedly cited 58 vacancies. This is a reported statement, not independently verified active headcount or the number of employees facing termination."},{"n":14,"title":"November 17 meeting","classification":"Dated source finding","sourceIds":["S5"],"answer":"Secondary reporting describes a unanimous motion to seek confidential legal advice about proposed budget reductions. No conclusion about private deliberations follows."},{"n":15,"title":"Patrol demand baseline","classification":"Dated source finding","sourceIds":["S6"],"answer":"The Sheriff reports about 36,378 calls in 2023 and 33,232 in 2024, a 3,146-call decline. This does not verify a 2026 increase or decrease."},{"n":16,"title":"Workload measure","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Track aggregate call volume, priority mix, service duration, response-time distribution, overdue cases and mutual aid together. Volume alone is not demand intensity."},{"n":17,"title":"Detention workload","classification":"Dated source finding","sourceIds":["S6"],"answer":"The 2024 report records 5,383 Judicial Intake bookings. Bookings are not daily custody population or proof of today's staffing requirements."},{"n":18,"title":"SRO historical baseline","classification":"Dated source finding","sourceIds":["S6"],"answer":"The 2024 report describes a seven-person SRO team, serving over 20 schools; 757 students received DARE instruction that year. Historical program scale is not current deployment or evidence of effectiveness."},{"n":19,"title":"District partnership","classification":"Dated source finding","sourceIds":["S7"],"answer":"District 70 describes SRO work alongside school personnel in prevention, law enforcement and safety planning."},{"n":20,"title":"Current SRO contract and positions","classification":"Not established","sourceIds":[],"answer":"Current agreement, cost sharing, actual staffed positions, proposed reductions, school-specific status and final decision remain unverified. Do not publish operational coverage gaps."},{"n":21,"title":"Child disclosure and trust","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"The supplied testimony describes trust-based disclosures of abuse and family hardship. Plausible continuity risk warrants review, but local counts, outcomes and counterfactuals are unknown."},{"n":22,"title":"Other reporting pathways","classification":"Dated source finding","sourceIds":["S11","S12"],"answer":"School employees and peace officers have reporting responsibilities. Colorado's child abuse hotline and Safe2Tell provide distinct channels; the latter is not a substitute for required abuse reporting or emergencies."},{"n":23,"title":"Immediate safety resources","classification":"Dated source finding","sourceIds":["S11","S12"],"answer":"For immediate danger call 911; suspected child abuse or neglect can be reported to 844-264-5437 or local authorities. Safe2Tell: 877-542-7233, safe2tell.org or text S2TCO to 738477."},{"n":24,"title":"Poverty is not abuse","classification":"Q analysis or practical guidance","sourceIds":["S11"],"answer":"Family homelessness or financial insecurity alone does not establish abuse. Preserve access to appropriate housing, food and supportive resources without treating hardship as culpability."},{"n":25,"title":"Evidence for SROs","classification":"Dated source finding","sourceIds":["S13"],"answer":"A 2023 national study estimated reductions in some kinds of school violence, no demonstrated prevention of gun-related incidents, and increased disciplinary actions, with disparities."},{"n":26,"title":"Counterevidence","classification":"Dated source finding","sourceIds":["S14"],"answer":"A 2023 systematic review did not establish a safety-promoting effect overall and identified concerns about exclusionary discipline. Underlying study limitations weaken causal certainty."},{"n":27,"title":"Child-impact gate","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Before changing the program, assess trust and access to reporting, emergency response, student wellbeing, equitable discipline, disability accommodations, referral continuity and education outcomes. Never publish identifiable student information."},{"n":28,"title":"Worker wellbeing","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Measure aggregate overtime, injuries, absences, turnover, training and recruitment. Do not interpret employee health records or personal circumstances as public data."},{"n":29,"title":"Capacity shock","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"When demand is variable and response capacity declines, waiting time can increase disproportionately. A hypothetical demand-to-capacity ratio of 0.80 becomes 0.889 after a 10% capacity loss. A budget percentage is not a capacity percentage; no local capacity estimate is made."},{"n":30,"title":"Net savings formula","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Gross avoided expenditure minus offsets: overtime, replacement training, separation costs, contract changes, lost reimbursements, and other incremental costs. Do not assign a financial price to a child's safety or treat uncertain liabilities as zero."},{"n":31,"title":"Funding alternative A","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Reallocate legally available recurring expenditure after verifying actual commitments. Protect mandatory duties and compare consequences for every service. No identified $4.89M offset is established."},{"n":32,"title":"Funding alternative B","classification":"Q analysis or practical guidance","sourceIds":["S7"],"answer":"Explore a district-county cost-share agreement, eligible recurring reimbursements and voluntary partnership. Verify existing agreement, authority and affordability before counting funds."},{"n":33,"title":"Operational alternative","classification":"Q analysis or practical guidance","sourceIds":["S15"],"answer":"Evaluate multidisciplinary school safety, counselors, trusted-adult continuity, reporting and non-police prevention alongside trained SRO capacity. No universal staffing recommendation follows."},{"n":34,"title":"Transition and fallback","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Use human-approved continuity plans before changes take effect. Pilot administrative efficiencies on noncritical tasks, preserve a manual fallback and evaluate actual results before expanding."},{"n":35,"title":"Financial crossover","classification":"Q analysis or practical guidance","sourceIds":["S20","S21"],"answer":"Connect county budget, jail debt, compensation, pension funding and audit costs. Distinguish capital from recurring funding, restricted from unrestricted dollars, and authorized from paid. See companion investigations. KRDO's November 17 municipal-offense jail agreement report creates a separate demand-side review: compare any additional custody days, incremental costs and intergovernmental reimbursement against the county's proposed service reductions. [S20,S21]"},{"n":36,"title":"LL and EE","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Reuse dated financial and service baselines; measure avoidable reporting and administrative effort. Do not label staff time recovered as cash saved without evidence."},{"n":37,"title":"T2Y and shadow","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Record testimony as attributed, official metrics as dated, future effects as scenarios, and missing records as unknown. Append corrections; no citizen or student profiles."},{"n":38,"title":"Twin and RX","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Connect agency-level responsibilities, funding and service outcomes, not live dispatch, facility weaknesses, school routes or deployment positions. Pause and correct unsupported data, preserve human decision authority."},{"n":39,"title":"Event horizons and LEAP","classification":"Dated source finding","sourceIds":["S17","S20"],"answer":"Official calendar lists December 4 for final Workday adjustments and December 10 for the public adoption hearing. Check official agendas for changes. Q proposes monthly follow-up after adoption, annual evaluation and multi-year workforce and safety review. Track November 23 City Council consideration of the proposed jail agreement separately from county budget adoption; county approval is also needed as reported by KRDO. [S20]"},{"n":40,"title":"Qified conclusion","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"A fiscal target needs an accountable service-continuity assessment. Compare practical alternatives and funding sources against lawful balanced budgets and measurable safety, dignity and equitable child outcomes. Neither assumed savings nor assumed harm should be presented as verified."}],"packet":{"schemaVersion":"1.0","lifecycle":"active","publicationStatus":"partial","evidenceStatus":"Dated public-source review and attributed supplied testimony","reviewDue":"2026-11-24","related":["qp-county-fiscal-review-2026","qp-county-pension-2026","qp-county-audit-cost-2026","qp-regional-fragmentation-2026","qp-regional-packets-2026"],"build":"Service continuity evaluation, financial savings model, child impact gate, reporting pathways and versioned public packet. No live safety operations.","privacy":"No child case records, school-specific gaps or deployment details. Testimonials separated from verified data."},"evidenceLeads":[{"id":"L1","title":"KRDO13 social-media link to November 18 sheriff layoff report","url":"https://krdo.com/news/2026/11/18/pueblo-sheriff-warns-layoffs/","observed":"2026-11-18","status":"supplied screenshot; article inaccessible on attempted read; specific figures and statements not verified","communitySignal":"Two short visible comments express unsurprised reactions; the third entry is a partially visible image. Relevance-ranked sample, not representative or additional claim evidence. No commenter names or screenshot published."}]});
 regionalStories.push(...[{"id":"qp-desert-hawk-finance-2026","title":"Desert Hawk Golf Course: what public records reveal about costs, debt and regional obligations","route":"desert-hawk-public-finances.html","checked":"2026-11-18","reviewBy":"2026-12-02","questions":["What are Desert Hawk Golf Course's financial details?","Is Desert Hawk Golf Course profitable?","Can Desert Hawk funds pay for sheriff deputies?"],"keywords":["Desert Hawk","golf course finances","golf course debt","golf course water","golf course subsidy"],"summary":"County 2024 audited statements show $238,560 operating income but a $1,667,877 negative net position. Pueblo West’s 2025 audit lists $7,613,306 in long-term notes plus a $457,000 land option. Public records are spread across two institutions; no freely transferable balance is established. [S1,S2]","sources":[{"id":"S1","title":"County 2024 ACFR — printed pages 9, 24–26, 29, 66, 133","url":"https://county.pueblo.org/sites/default/files/2025-11/Pueblo%20County%20Annual%20Comprehensive%20Financial%20Report%202024.pdf"},{"id":"S2","title":"Pueblo West 2025 ACFR — printed page 26 (PDF page 55)","url":"https://www.pueblowestmetro.us/Archive.aspx?ADID=114"},{"id":"S3","title":"Pueblo West May 2026 board summary — IGA and water explanation","url":"https://www.pueblowestmetro.us/Blog.aspx?IID=10"},{"id":"S4","title":"County 2027 proposed budget presentation — slide 9","url":"https://county.pueblo.org/sites/default/files/2026-10/2027%20Proposed%20Budget%20SB.pdf"},{"id":"S5","title":"County Desert Hawk board description and 2001 resolution","url":"https://county.pueblo.org/boards-and-commissions-department/accepting-applications-desert-hawk-golf-course-management-board"},{"id":"S6","title":"Official board membership registry","url":"https://pueblocounty.granicus.com/boards/w/0b77065d49fd192c/boards/39696"},{"id":"S7","title":"August 19, 2026 management board meeting — secondary summary, original minutes not verified","url":"https://www.zonewire.co/meetings/pueblo-county/8400"},{"id":"S8","title":"Pueblo West annual reports and budgets","url":"https://www.pueblowestmetro.us/548/Budget-and-Annual-Financial-Reports"}],"chapters":[{"kind":"context","heading":"Public-source finding and scope","text":"A supplied comment asks why Desert Hawk financial details have not been released. Annual financial details are available, although split across agencies. The county’s latest audited golf statements reviewed here are for 2024; Pueblo West’s 2025 audit supplies a newer creditor-side view. A missing 2025 county report does not erase the published records. [S1,S2,S8]"},{"kind":"context","heading":"Acquisition and purpose","text":"The county acquired the course in 2000, citing recreation and preservation of area property values. Resolution 01-134, May 8, 2001, established a cooperative management board. The original 2005 acquisition-refinancing COPs were fully retired in 2024. Other obligations survive. [S1,S5]"},{"kind":"context","heading":"Management and responsibility","text":"The official board registry lists seven seats, shared county/district appointments and the three county commissioners among members. A county enterprise fund reports the golf activity. Board membership is not evidence of personal wrongdoing. [S1,S5,S6]"},{"kind":"context","heading":"Operating results","text":"2024 customer/service revenue $1,531,007 less operating expenses $1,292,447 equals operating income $238,560 (15.58% margin). Income before transfers is $245,184; $45,322 transfers in raise net-position change to $290,506. Positive operating income does not establish financial independence or cash available to transfer. [S1 p25]"},{"kind":"context","heading":"Operating expense ledger","text":"Contract fees $535,567; utilities and communications $323,820; supplies $193,504; depreciation $88,897; personnel $49,709; repairs/maintenance $42,995; insurance $30,038; professional services $27,522; equipment rent $395. These total $1,292,447; utilities includes more than water and contracts do not identify individual payees. [S1 p25]"},{"kind":"context","heading":"Assets, liabilities and net position","text":"Assets $6,740,132 include cash $277,275, investments $898,089, net capital assets $5,076,762 and development land $457,000. Liabilities $8,396,323 plus deferred inflows $11,686 result in net position −$1,667,877; unrestricted net position −$6,699,928. Book values are not appraisals or sellable cash. [S1 p24]"},{"kind":"context","heading":"Cash flow and retired financing","text":"Operating cash flow $340,307; transfer receipts $45,322; capital/financing cash outflow $730,750 (including $580,000 COP principal); investing net outflow $94,890. The net decline is $440,011, from $717,286 to $277,275 cash. The county narrative says General Fund transfers were not needed for COP repayment in 2024, yet the enterprise statements show a transfer in; origin and purpose require reconciliation, not an assumption of operating subsidy. [S1 pp9,26]"},{"kind":"context","heading":"County obligation breakdown","text":"At end 2024 county reports $6,334,553 non-interest-bearing loan, $1,279,813 water advance, $457,000 purchase option; total $8,071,366. Other current obligations include $212,715 due to other funds; do not add a second copy of the district receivable to regional debt. [S1 pp24,66]"},{"kind":"context","heading":"Newer district-side evidence","text":"2025 Pueblo West audit lists $6,078,478 historical operating/debt-service note, $255,000 acquisition/other note and $1,279,828 water note; total notes $7,613,306, plus $457,000 land option = $8,070,306. It reports notes not scheduled to be collected the subsequent year. County 2024 versus district 2025 totals differ by $1,060; dates and classifications differ, and no repayment can be inferred solely from that difference. [S2 p26]"},{"kind":"context","heading":"Water cost and counterevidence","text":"The IGA treats water not covered by annual revenue before 2011 as noninterest-bearing loans and provides untreated water at no more than actual district cost. District’s May 2026 statement says the golf course has paid under agreement terms since 2011. Hence $8.07M is not an ordinary overdue water bill. Current consumption, rate, metering and repair costs require independent comparison. [S1,S2,S3]"},{"kind":"context","heading":"Repayment and event horizon","text":"Repayments are limited to excess revenues over cash disbursements and $500,000 per year for all applicable loans. For the 2025 district notes alone (excluding land option), illustrative constant annual payments $100k, $250k, $500k imply 77, 31, 16 payment years, assuming no further advances or changes and all payment directed to those notes. These are bounds/scenarios, not an enforceable amortization schedule. [S1,S2]"},{"kind":"context","heading":"2027 budget and decision","text":"County slides project 2026 ending budgetary balance $1.29M, 2027 revenue $1.82M, expense $1.55M and ending $1.56M, all millions. The 2026 inputs are unaudited. An August 19 secondary meeting summary reports equipment reductions and fee decisions; verify original minutes before relying on contract/fee changes. [S4,S7]"},{"kind":"context","heading":"Water infrastructure and asset choices","text":"Investigate irrigation replacement, lifecycle cost, measured losses and water affordability. Secondary meeting summary reports infrastructure discussion, but no leak estimates or funding claims are treated as verified. Compare retain/reinvest, competitively contract, restructure IGA, lease, sell or change use only after appraisals, legal review, access and debt/land-option protections. [S7]"},{"kind":"context","heading":"Public safety crossover","text":"Do not count the $1.56M projected golf budgetary balance, the $7.61M notes or the sale book value as freely available sheriff funds. Assess legal authority, obligations, deferred maintenance, debt repayment priorities, revenue loss and recurring net effect separately. Compare golf recreation and affordability, water affordability, emergency resources and child/family effects without assuming service tradeoffs are zero."},{"kind":"context","heading":"Q processing, LL, EE and T2Y","text":"Retain fiscal date, entity, fund, accounting basis, item, counterparty, value and source page; match district assets to county liabilities only at common dates. Record public statements as attributed, do not replicate commentary identities. Reuse audited rows across budget, water, debt, regional twin and public asset packets; review contradictions rather than overwriting them."},{"kind":"context","heading":"RX, implementation and future","text":"Build an asset/IGA packet with ownership, financing, repayment, transfers, water volumes and lifecycle maintenance; publish costed alternatives and annual totals. Trigger review at 2027 budget adoption, next County ACFR and any IGA amendment, then year 3 and 5 repayment/capital comparisons. Human decision authority remains with participating governments. No automated financial action."}],"unknowns":["County 2025/2026 audited enterprise results, transfer counterparties and final 2027 appropriation not verified.","Current IGA amendments, repayment schedule, actual water usage, deferred maintenance, appraisals and contractor payments not reconciled.","Pueblo West 2025 audit text retrieved; page screenshot failed. County key pages and budget slide were visually verified.","No finding of illegal subsidy or legally transferable funds."],"packet":{"schemaVersion":"1.0","lifecycle":"active","publicationStatus":"partial","evidenceStatus":"Dated public-source analysis and supplied screenshot observations","reviewDue":"2026-12-02","related":["qp-county-fiscal-review-2026","qp-regional-fragmentation-2026","qp-county-public-safety-child-2026"],"build":"Cross-entity obligation register, public asset lifecycle packet, conditional repayment model, regional cost comparison and audit-ready data.","privacy":"No private commenter identities or screenshots republished.","coverage":"40 substantive perspectives; active and incomplete evidence lifecycle"},"coverage40":[{"n":1,"title":"Public question","classification":"Supplied screenshot observation","sourceIds":[],"answer":"One supplied comment asks why the county-owned course's financial details have not been released. It is a research lead, not proof of concealment. Annual statements are already available."},{"n":2,"title":"Ownership history","classification":"Dated source finding","sourceIds":["S1"],"answer":"The county acquired Desert Hawk in 2000. Public recreation and property-value preservation are described purposes, not quantified benefits."},{"n":3,"title":"Intergovernmental agreement","classification":"Dated source finding","sourceIds":["S5"],"answer":"Resolution 01-134 of May 8, 2001 established a joint management arrangement. Review current amendments before relying on original terms."},{"n":4,"title":"Management board","classification":"Dated source finding","sourceIds":["S6"],"answer":"The registry lists a seven-seat board with county and district appointments. Track public votes and terms; membership alone does not establish responsibility for an individual transaction."},{"n":5,"title":"Reporting architecture","classification":"Dated source finding","sourceIds":["S1","S2","S8"],"answer":"County reports an enterprise fund and Pueblo West reports creditor-side balances. Both are needed; do not add overlapping obligations."},{"n":6,"title":"2024 operating revenue","classification":"Dated source finding","sourceIds":["S1"],"answer":"$1,531,007, classified as operating revenue, not unrestricted General Fund resources."},{"n":7,"title":"2024 operating expenditure","classification":"Dated source finding","sourceIds":["S1"],"answer":"$1,292,447, including depreciation. Accrual expenses differ from cash disbursements."},{"n":8,"title":"Operating margin","classification":"Q analysis or practical guidance","sourceIds":["S1"],"answer":"$238,560 operating income divided by $1,531,007 revenue equals about 15.58%. One positive year does not establish long-run self-sufficiency."},{"n":9,"title":"Contract expense","classification":"Dated source finding","sourceIds":["S1"],"answer":"$535,567 contract fees in 2024, around 41.4% of operating expenses. Vendor identities and scope require the contract register."},{"n":10,"title":"Utilities and supplies","classification":"Dated source finding","sourceIds":["S1"],"answer":"Utilities/communications $323,820 and supplies $193,504. Utility total is not a standalone water bill."},{"n":11,"title":"Other operating expenses","classification":"Dated source finding","sourceIds":["S1"],"answer":"Depreciation $88,897; personnel $49,709; repairs $42,995; insurance $30,038; professional services $27,522; equipment rental $395."},{"n":12,"title":"Income and transfers","classification":"Dated source finding","sourceIds":["S1"],"answer":"$245,184 income before transfers plus $45,322 transfers in equals $290,506 change in net position. Transfer source and purpose remain unresolved."},{"n":13,"title":"Assets","classification":"Dated source finding","sourceIds":["S1"],"answer":"2024 total assets $6,740,132, including $5,076,762 net capital assets and $457,000 development land. Book value is not a market appraisal."},{"n":14,"title":"Liabilities","classification":"Dated source finding","sourceIds":["S1"],"answer":"2024 total liabilities $8,396,323; deferred inflows $11,686. Separate borrowing from trade and interfund obligations."},{"n":15,"title":"Net position","classification":"Q analysis or practical guidance","sourceIds":["S1"],"answer":"$6,740,132 minus $8,396,323 minus $11,686 equals negative $1,667,877. Negative net position is not proof of imminent cash insolvency."},{"n":16,"title":"Unrestricted net position","classification":"Dated source finding","sourceIds":["S1"],"answer":"Negative $6,699,928 in 2024. This accounting measure is not a transferable cash balance."},{"n":17,"title":"Cash and investments","classification":"Dated source finding","sourceIds":["S1"],"answer":"2024 ending cash $277,275 and investments $898,089. Liquidity must be assessed against obligations and legal restrictions."},{"n":18,"title":"Cash-flow bridge","classification":"Q analysis or practical guidance","sourceIds":["S1"],"answer":"$340,307 operating cash plus $45,322 transfers less $730,750 capital/financing outflow and $94,890 investing outflow equals a $440,011 cash decrease."},{"n":19,"title":"Acquisition financing retired","classification":"Dated source finding","sourceIds":["S1"],"answer":"Original acquisition-refinancing COPs were retired in 2024; capital/financing cash flows include $580,000 principal. This does not repay all district advances."},{"n":20,"title":"Historical district advances","classification":"Dated source finding","sourceIds":["S1"],"answer":"County 2024 loan $6,334,553, water advance $1,279,813 and option $457,000 total $8,071,366."},{"n":21,"title":"Newer district audit","classification":"Dated source finding","sourceIds":["S2"],"answer":"2025 district notes: $6,078,478, $255,000 and $1,279,828, totaling $7,613,306, plus $457,000 option. The report says notes are not scheduled for collection in the subsequent year."},{"n":22,"title":"Matching both sides","classification":"Q analysis or practical guidance","sourceIds":["S1","S2"],"answer":"County 2024 total and district 2025 total differ by $1,060. Different dates and classifications prevent identifying a payment from that difference alone."},{"n":23,"title":"Water agreement","classification":"Dated source finding","sourceIds":["S1","S2","S3"],"answer":"Historical water costs were structured as noninterest-bearing advances. District says agreement terms have been followed since 2011. Do not call all advances delinquent water bills."},{"n":24,"title":"Repayment restriction","classification":"Dated source finding","sourceIds":["S1","S2"],"answer":"Repayment depends on excess receipts over cash disbursements and an annual aggregate $500,000 maximum under reported terms. Verify amendments."},{"n":25,"title":"Repayment scenarios","classification":"Q analysis or practical guidance","sourceIds":["S2"],"answer":"$7,613,306 notes alone require 77 years at $100,000, 31 at $250,000 or 16 at $500,000, with no new advances and unchanged terms. No payment is forecast."},{"n":26,"title":"Projected 2027 budget","classification":"Dated source finding","sourceIds":["S4"],"answer":"2026 ending budgetary balance $1.29M, 2027 revenue $1.82M, expenditure $1.55M, ending $1.56M, rounded. These are not audited actuals."},{"n":27,"title":"Current financial position","classification":"Not established","sourceIds":[],"answer":"County 2025 audited enterprise results and 2026 closed accounts are not located in this investigation. District 2025 figures cannot substitute for them."},{"n":28,"title":"Transfer authority","classification":"Not established","sourceIds":[],"answer":"No legal determination of cash transferable to public safety. Review enterprise restrictions, agreement, outstanding commitments and reserve requirements."},{"n":29,"title":"Capital condition","classification":"Not established","sourceIds":[],"answer":"Current irrigation condition, replacement estimates, deferred maintenance, asset appraisals and independent water-loss measurements remain unverified."},{"n":30,"title":"Water efficiency","classification":"Q analysis or practical guidance","sourceIds":["S3","S7"],"answer":"Compare annual measured water volumes, actual supply cost, crop/turf demand and irrigation maintenance. An efficiency project needs measured baseline, bids, lifetime savings and environmental review."},{"n":31,"title":"Retain and improve","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Model user fees, realistic demand, maintenance capital and cash available after repayment. Preserve access and avoid assuming rate increases cause no loss of users."},{"n":32,"title":"Lease or contract","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Compare public procurement, performance standards, revenue sharing, insurance, water obligations and termination rights against the public operation baseline."},{"n":33,"title":"Sale or conversion","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Require independent appraisal, option and deed review, land-use approval, net sale proceeds after obligations and recurring revenue/service consequences; no sale price is asserted."},{"n":34,"title":"Taxpayer and recreation effects","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Compare distribution of costs and recreational access across county and district populations; account for non-golf users and alternative services."},{"n":35,"title":"Child and family impact","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Assess youth recreation affordability and household cost burdens alongside emergency-service access. No causal or dollar child impact has been measured."},{"n":36,"title":"Regional financial crossover","classification":"Q analysis or practical guidance","sourceIds":["S1","S2","S4"],"answer":"Match reciprocal debts on the same reporting date. Do not count notes as new cash or treat enterprise income as a verified alternative to Sheriff reductions."},{"n":37,"title":"LL and EE","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Reuse the original audited tables, reconcile counterparties once, record discrepancies and measure preparation time and costs before claiming efficiency."},{"n":38,"title":"T2Y, twin and shadow","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Version the public asset, agreement, financial snapshots and related water/finance entities; keep factual states separate from scenarios. No live asset control."},{"n":39,"title":"RX and governance gate","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Publish comparable retain, restructure and exit options, independent review, documented votes, affordability and a rollback or contingency plan; human authorities decide."},{"n":40,"title":"Event horizons and Qified synthesis","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Recheck final 2027 budget, next county audit and agreement changes, then year 3 and 5 costs and repayment. Publish accessible data now despite incomplete records; no certified audit or finding of misconduct."}]},{"id":"qp-county-budget-explanation-2026","title":"Pueblo County’s budget realities: reconstructing the commissioners’ public explanation","route":"county-budget-explanation-reconciled.html","checked":"2026-11-18","reviewBy":"2026-12-02","questions":["What is the commissioners' explanation for the Pueblo County budget crisis?","Do Pueblo County's 2027 budget graphics reconcile?","How much did county detention expenses increase?"],"keywords":["budget realities","Paula McPheeters budget","Robert Choi budget","capital spending","marijuana revenue decline","cost of maintaining services"],"summary":"Commissioner-shared graphics describe capital commitments, declining marijuana revenue and rising service costs. Recalculation shows $19.068M lower proposed revenue/sources versus the 2026 budget, with lower grants and zero proposed financing accounting for $17.928M of that net change. A proposed $1.265M surplus is a narrow margin, not a final result.","sources":[{"id":"S1","title":"County official budget portal — preliminary book and presentations","url":"https://county.pueblo.org/budget-and-finance-department/2027-budget"},{"id":"S2","title":"County October 2026 proposed budget presentation, slide 9 and other slides","url":"https://county.pueblo.org/sites/default/files/2026-10/2027%20Proposed%20Budget%20SB.pdf"},{"id":"S3","title":"County 2024 ACFR — governmental fund and debt statements","url":"https://county.pueblo.org/sites/default/files/2025-11/Pueblo%20County%20Annual%20Comprehensive%20Financial%20Report%202024.pdf"},{"id":"S4","title":"County November 2026 progress and policy report","url":"https://www.pueblocounty.gov/board-county-commissioners-office/what-we-are-working"},{"id":"S5","title":"Pueblo Ledger November 14 — secondary description of preliminary budget","url":"https://puebloledger.com/government-watch/pueblo-2027-budgets-city-county/"}],"chapters":[{"kind":"context","heading":"Evidence intake","text":"Nine supplied screenshots include a resident question and overlapping captures of a post attributed to Commissioner Paula McPheeters crediting CAO Robert Choi’s 2027 preliminary budget. Deduplicate repeated graphics; do not add overlapping engagement numbers. The post showed 16 reactions, 4 comments and 15 shares in one capture, not a representative survey. The original post and full preliminary PDF could not be independently retrieved. Figures attributed to screenshots are labeled separately from audited or verified documents."},{"kind":"context","heading":"Administration's explanation","text":"The post argues the county faces structural problems: historical capital projects, debt service, sustained marijuana receipts decline and higher recurring costs. These can all be real pressures; historical authorization and current budget management are different responsibilities. The original jail refinancing claim concerns initial financing, not every later amendment or payment. [S1–S5 and supplied graphics]"},{"kind":"context","heading":"Capital and debt","text":"Supplied capital graphic: governmental capital outlays were $10.9M in 2021, $21.2M in 2022, $36.8M in 2023, $118.85M in 2024; debt payments in 2024 $19.83M. 2024 capital outlays are about 10.9 times 2021. Capital spending, financing principal and current operating expense are distinct. The graphic identifies jail/roadway, Workday and Beulah water as commitments; project-specific award, funding source, contract changes and actuals are not established by totals alone."},{"kind":"context","heading":"Marijuana revenue","text":"Supplied graph: 2019 $6.0M, 2020 $13.7M, 2021 $14.3M, 2022 $9.3M, 2023 $7.9M, 2024 $6.6M, 2025 $5.39M (rounded graph $5.4M). It reports a 62.3% peak-to-2025 fall, $8.90M lower revenue and rate change from 3.5% to 6% in 2020. Four consecutive lower receipts following 2021 are a planning warning; no conclusion about individual knowledge or intent follows. These are combined tax streams, not all unrestricted General Fund revenue."},{"kind":"context","heading":"Exact revenue table","text":"Supplied graphic, dollars, order 2025 recorded / 2026 budget / 2027 proposed: property 55,719,758 / 61,129,747 / 59,232,895; sales/use 31,114,375 / 32,352,500 / 32,370,500; ownership 4,815,614 / 5,000,000 / 5,000,000; fees/licenses/fines 9,972,510 / 11,890,980 / 12,570,736; grants 7,330,548 / 18,306,931 / 5,879,043; investments 2,260,187 / 1,910,000 / 2,310,000; transfers 0 / 1,465,000 / 1,000,000; other 2,061,413 / 4,179,427 / 4,303,427; financing 3,686,000 / 5,500,000 / 0."},{"kind":"context","heading":"Revenue reconciliation","text":"Displayed totals $116,960,406 / $141,734,585 / $122,666,601. Row sum for 2025 is $116,960,405, a $1 difference; 2026 and 2027 reconcile exactly. 2027 is $19,067,984 below 2026 budget; grant decrease $12,427,888 plus financing decrease $5,500,000 = $17,927,888 (94.02% of net decrease). Property decreases $1,896,852; sales rises $18,000. These are proposal-versus-budget changes not actual losses or proof grant funds could pay for eligible personnel."},{"kind":"context","heading":"Recurring revenue nuance","text":"2025 recorded total includes $3.686M financing, whereas 2027 proposal has zero financing. Proposed total is $5,706,195 greater than the displayed 2025 recorded total; excluding financing, difference $9,392,195. Grants/transfers may still be temporary or restricted, so these comparisons do not establish a structural operating surplus. Do not compare preliminary 2025 recorded numbers as audited actuals."},{"kind":"context","heading":"Six cost drivers","text":"Supplied graphic, 2023 actual / 2025 recorded: property/liability insurance $967,345 / $1,658,262; detention medical $4,656,465 / $5,894,700; health claims/admin $13,404,845 / $15,879,224; utilities $2,410,939 / $2,674,738; repairs/maintenance contracts $395,586 / $1,017,949; detention overtime $1,779,099 / $2,445,239. Total $23,614,279 to $29,570,112 = $5,955,833 increase (25.22%)."},{"kind":"context","heading":"Detention crossover","text":"Medical increase $1,238,235 (26.59%) plus overtime increase $666,140 (37.44%) = $1,904,375, or about 32% of the selected cost rise. These are gross cost areas, not the whole sheriff budget or verified causal effects of the new jail. Health claims/admin is shown before reimbursements. Connect staffing, custody demand, city–county agreements, contracts and health coverage; do not count these increases twice."},{"kind":"context","heading":"Budget exact arithmetic","text":"Supplied graphic lists revenue/sources $122,666,601; base expenditures $131,213,309; reported base shortfall $8,546,709; reductions $9,811,472; proposed expenditures $121,401,837; reported surplus $1,264,763. Recalculation gives shortfall $8,546,708, expenses $121,401,837, surplus $1,264,764. Two one-dollar differences likely underlying precision/rounding; not evidence of lost money. Reported surplus is 1.031% of proposed revenue."},{"kind":"context","heading":"Margin stress test","text":"Holding other items constant, 1% revenue loss $1,226,666 leaves about $38,097 of reported surplus. 90% attainment of the $9,811,472 reduction gives $283,616. Budget-balance headroom is not evidence that reserve targets or services are adequately funded. Do not combine annual shock with the separately projected opening balance."},{"kind":"context","heading":"Opening balance and fiscal policy","text":"October slide 9 expressly says the opening balance incorporates $7M anticipated asset sale and $15M anticipated COP. No financing in the 2027 annual revenue table does not contradict possible 2026 financing. Separate years and verify transactions. County progress report says policy sets 10% minimum and 16.67% target; subsequent schedule and exact eligible reserve measure need confirmation. [S2,S4]"},{"kind":"context","heading":"Inherited versus current governance","text":"Assign each project original authorization, later amendments, new financing, approved budget, expenditure, forecast and operating handoff to independently dated resolutions. The 2024 audit documents lease obligations but alone does not establish a complete responsibility matrix. Do not accuse a named official or exonerate all current decisions solely from the graphic. [S3]"},{"kind":"context","heading":"Options and child impact","text":"Compare recurring-cost controls, contract renewal, job vacancy treatment, debt and capital plans, restricted grant continuity and public safety service assessment. Evaluate prevention, detention healthcare, staffing, child reporting/education services and families receiving grants. No confirmed equivalent savings or causal harms claimed."},{"kind":"context","heading":"Q processing, LL, EE, T2Y and shadow","text":"Record screenshot-derived rows as source observations, not final audit figures; retain original display totals and recalculated sums. Version the November communications, match the original budget and audit when available, never overwrite historical figures silently. Reuse data across pension, public safety, jail, Desert Hawk and regional packets; separate staff time saved from cash savings."},{"kind":"context","heading":"RX, procurement and leap","text":"Require project authorization packets with 10–30 year debt, operations, staffing, maintenance, revenue sensitivities, contract commitments and exit plan; review Workday interoperability before new technology spending. A full-cost capital plan and monthly exception dashboard can help prevent reconstruction. Test read-only on historical figures; human authorization required."},{"kind":"context","heading":"Event horizons","text":"Before final 2027 budget adoption, update figures and alternatives; publish actual-vs-budget plus debt and grant reconciliation monthly in 2027. Compare reserve progress, recurring income and service outcomes through 2029 and 2031. No claim these practices are fully implemented. [S4]"}],"unknowns":["Original post and complete preliminary budget book inaccessible; screenshot figures are attributed, not independently audited.","2025 audited actuals, 2026 actual results, project-by-project costs and grant-specific restrictions not reconciled.","Actual service reductions, final budget and financing transactions unverified."],"packet":{"schemaVersion":"1.0","lifecycle":"active","publicationStatus":"partial","evidenceStatus":"Dated public-source analysis and supplied screenshot observations","reviewDue":"2026-12-02","related":["qp-county-fiscal-review-2026","qp-county-public-safety-child-2026","qp-desert-hawk-finance-2026","qp-county-audit-cost-2026","qp-regional-packets-2026"],"build":"Exact-dollar screenshot transcription, revenue and cost bridges, operating margin stress checks, capital authorization ledger and public budget-packet specification.","privacy":"No private commenter identities or screenshots republished.","coverage":"40 substantive perspectives; active and incomplete evidence lifecycle"},"coverage40":[{"n":1,"title":"Evidence identity","classification":"Supplied screenshot observation","sourceIds":[],"answer":"Nine supplied screenshots show overlapping commissioner-post graphics and a resident's golf-course question. Deduplicate repeated captures and keep their original displayed amounts."},{"n":2,"title":"Attributed explanation","classification":"Supplied screenshot observation","sourceIds":[],"answer":"The post attributed to Commissioner McPheeters credits CAO Robert Choi's preliminary budget for structural challenges. The original post and full underlying book were not independently retrieved."},{"n":3,"title":"Capital outlay baseline","classification":"Supplied screenshot observation","sourceIds":[],"answer":"Governmental capital outlay: $10.9M 2021, $21.2M 2022, $36.8M 2023 and $118.85M 2024. Figures are displayed in the supplied graphic."},{"n":4,"title":"Capital spending scale","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"$118.85M / $10.9M ≈ 10.9. A large capital-outlay year does not mean equivalent recurring operating costs or freely available cash."},{"n":5,"title":"Debt payments","classification":"Supplied screenshot observation","sourceIds":[],"answer":"The graphic reports $19.83M governmental-fund debt payments in 2024. Debt service is not outstanding principal; reconcile original debt schedules."},{"n":6,"title":"Capital commitments","classification":"Supplied screenshot observation","sourceIds":[],"answer":"Graphic cites jail and related roadway, Workday and Beulah water infrastructure. Project-level awards, amendments, draws and lifecycle costs cannot be separated from the graphic alone."},{"n":7,"title":"Original jail financing","classification":"Supplied screenshot observation","sourceIds":[],"answer":"Graphic attributes original financing to an earlier board. Verify authorization separately from later amendments, payments, forecasts and operational decisions."},{"n":8,"title":"Cannabis tax receipts","classification":"Supplied screenshot observation","sourceIds":[],"answer":"2019 $6.0M, 2020 $13.7M, 2021 $14.3M, 2022 $9.3M, 2023 $7.9M, 2024 $6.6M, 2025 $5.39M per text. Graph rounds 2025 to $5.4M."},{"n":9,"title":"Revenue warning signal","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Four consecutive annual decreases after the 2021 peak were visible in the graph. It reports 62.3% decline and $8.90M loss versus peak, not a causal proof about individual officials."},{"n":10,"title":"Tax rate change","classification":"Supplied screenshot observation","sourceIds":[],"answer":"Graphic reports local rate increasing from 3.5% to 6% in 2020. Receipts combine streams; do not assume all can pay unrestricted operations."},{"n":11,"title":"Reporting stages","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"2025 recorded, 2026 budget and 2027 proposed are different stages. The 2025 amounts are not an audited final ledger and the 2027 amounts are not enacted."},{"n":12,"title":"Property and sales taxes","classification":"Supplied screenshot observation","sourceIds":[],"answer":"2026 budget to 2027 proposed property tax $61,129,747 to $59,232,895; sales/use $32,352,500 to $32,370,500. Property decreases $1,896,852; sales increases $18,000."},{"n":13,"title":"Ownership taxes and fees","classification":"Supplied screenshot observation","sourceIds":[],"answer":"Specific ownership $5M in both years. Fees/licenses/fines $11,890,980 to $12,570,736, increase $679,756. Fee burden deserves assessment."},{"n":14,"title":"Grant funding","classification":"Supplied screenshot observation","sourceIds":[],"answer":"$18,306,931 budgeted in 2026 versus $5,879,043 proposed in 2027, difference $12,427,888. Grant-specific timing, restrictions and associated expenditures remain unknown."},{"n":15,"title":"Financing proceeds","classification":"Supplied screenshot observation","sourceIds":[],"answer":"2026 budget $5.5M, 2027 proposed zero; 2025 recorded $3.686M. Financing is not recurring earned revenue, and the screenshot cautions proceeds are not reconciled as final."},{"n":16,"title":"Other revenue sources","classification":"Supplied screenshot observation","sourceIds":[],"answer":"Investments $1.91M to $2.31M, transfers $1.465M to $1M, other revenue $4,179,427 to $4,303,427. These are proposal-to-budget amounts."},{"n":17,"title":"Row reconciliation","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"2025 rows sum to $116,960,405 against displayed $116,960,406. 2026 $141,734,585 and 2027 $122,666,601 reconcile. Keep $1 discrepancy in the record, not a claim of missing money."},{"n":18,"title":"Revenue bridge","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Net 2026 budget-to-2027 proposal decrease $19,067,984; grants plus financing decreases $17,927,888 (about 94.02%). This is not a measure of actual loss."},{"n":19,"title":"2025 comparison","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"2027 proposed sources exceed 2025 displayed recorded sources by $5,706,195; excluding 2025 financing gives $9,392,195. Neither proves stable recurring revenue."},{"n":20,"title":"Insurance","classification":"Supplied screenshot observation","sourceIds":[],"answer":"$967,345 in 2023 and $1,658,262 recorded in 2025: $690,917 increase (about 71.42%). Examine premium and coverage terms separately."},{"n":21,"title":"Detention medical","classification":"Supplied screenshot observation","sourceIds":[],"answer":"$4,656,465 to $5,894,700, increase $1,238,235 (26.59%). Medical demand, contracts and custody populations need reconciliation."},{"n":22,"title":"Health claims","classification":"Supplied screenshot observation","sourceIds":[],"answer":"$13,404,845 to $15,879,224, increase $2,474,379 (18.46%); before reimbursements according to graphic. Net expenditure remains unverified."},{"n":23,"title":"Utility expenditures","classification":"Supplied screenshot observation","sourceIds":[],"answer":"$2,410,939 to $2,674,738, increase $263,799 (10.94%). Tariff, demand and facility changes should be separated."},{"n":24,"title":"Maintenance spending","classification":"Supplied screenshot observation","sourceIds":[],"answer":"$395,586 to $1,017,949, increase $622,363 (157.33%). Distinguish deferred maintenance catch-up from recurring contracts."},{"n":25,"title":"Detention overtime","classification":"Supplied screenshot observation","sourceIds":[],"answer":"$1,779,099 to $2,445,239, increase $666,140 (37.44%). Do not infer actual staffing counts from overtime dollars."},{"n":26,"title":"Selected cost bridge","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Selected costs rise from $23,614,279 to $29,570,112: $5,955,833 (25.22%). These six lines are not the entire General Fund."},{"n":27,"title":"Jail cost crossover","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Medical and overtime increases total $1,904,375 (about 32% of selected cost rise). This does not establish new jail causation; connect staffing and municipal custody proposal."},{"n":28,"title":"Base shortfall","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Displayed revenues $122,666,601 less base $131,213,309 implies −$8,546,708; graphic reports −$8,546,709. Retain original and recalculation."},{"n":29,"title":"Department reductions","classification":"Supplied screenshot observation","sourceIds":[],"answer":"Reported reduction plan $9,811,472. The graphic does not establish final layoffs, achievable offsets or service continuity."},{"n":30,"title":"Proposed expenditure","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"$131,213,309 − $9,811,472 = $121,401,837, exactly matching displayed proposed expenditure."},{"n":31,"title":"Surplus precision","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Revenue less proposed expenditure is $1,264,764; graphic displays $1,264,763. A one-dollar difference may reflect rounding; both imply roughly 1.03% headroom."},{"n":32,"title":"Stress and forecast","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"At 1% less revenue, reported surplus falls to about $38,097. At 90% reduction attainment with revenue unchanged, it is about $283,616. These are not predictions."},{"n":33,"title":"Opening balance and financing","classification":"Dated source finding","sourceIds":["S2"],"answer":"October slide 9 includes anticipated $7M asset sale and $15M COP in opening assumptions. Zero proposed 2027 annual financing is a separate concept; avoid double counting."},{"n":34,"title":"Reserves","classification":"Dated source finding","sourceIds":["S4"],"answer":"County progress report describes a 10% minimum and 16.67% target. Verify eligible base, timing and actually available reserves before assigning compliance."},{"n":35,"title":"Fiscal accountability","classification":"Q analysis or practical guidance","sourceIds":["S3"],"answer":"Create a decision-by-date timeline for historical commitments and later changes. Separate record-backed authority from assumptions about officials' knowledge or intent."},{"n":36,"title":"Child and service continuity","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Test reductions against prevention, child protection, family grant services, detention care, school safety and equitable access. Aggregate indicators only; no child case disclosure."},{"n":37,"title":"Options and grant bridge","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Compare lawful recurrent sources, temporary programs ending, related grant expenses, contract renewals and staffing alternatives. No $9.81M offset has been verified."},{"n":38,"title":"AI-ready procurement and EE","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Workday and other investments require export rights, reconciliation, total lifecycle cost and tested controls. Reuse source rows and benchmark staff time; don't claim software fixes an accounting failure."},{"n":39,"title":"LL, RX, T2Y and twin/shadow","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Store observed figures, exact formulas, dated approvals and scenarios separately, attach source lineage, review inconsistencies, and retain corrections and prior states. Financial decisions remain human-controlled."},{"n":40,"title":"Event horizons and Qified conclusion","classification":"Q analysis or practical guidance","sourceIds":[],"answer":"Review final budget and financing, monthly actuals and next audit, then year 3/5 capital and reserve results. Distinguish explanation from proof, and proposed balance from achieved recovery. Original full budget and 2025 audit remain gaps."}]}]);
 const allStories=[...edition.stories,...priorityStories,...regionalStories];
 const norm=v=>String(v??'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
 const byId=id=>allStories.find(s=>s.id.toLowerCase()===String(id).toLowerCase())||null;
 const exact=q=>{const hits=allStories.filter(s=>s.questions.some(a=>norm(a)===norm(q)));return hits.length===1?hits[0]:null;};
 const related=q=>allStories.filter(s=>(s.keywords||[]).some(k=>(' '+norm(q)+' ').includes(' '+norm(k)+' ')));
 const api={edition,priorityStories,regionalStories,allStories,byId,exact,related};if(root)root.QPStoryEditions=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window!=='undefined'?window:null);
